[When(@"I update view pane ""([^""]*)"" as follows")]
        [StepDefinitionDescription(Documentation = "Updates data from the specified pane.  Must be preceded by a step to select data from a view")]
        public void WhenIUpdateViewPaneAsFollows(string paneName, Table table)
        {
            if (_repository == null) StepLog.LogFatal("No data selected.  Use 'When I select view pane <pane> data from <view>");
            VariableManager.ExpandTableVariables(table);
            _repository.Update(VariableManager.ExpandVariables(paneName), table);
        }

