[Given("indexes as follows")]
        [StepDefinitionDescription(Documentation =
            "Defines one or more indexes to control a subsequent step.  Corresponds to the 'Indexes' tab in the GUI")]
        [RequiredColumn(Field = IndexFolderField)]
        [RequiredColumn(Field = IndexValueField)]
        public void GivenIndexesAsFollows(Table table)
        {
            VariableManager.ExpandTableVariables(table);
            CommonStepParameters.CheckTable(table);
            foreach (var row in table.Rows)
                _parameterRepository.AddIndex(row[IndexFolderField], row[IndexValueField]);
        }

[Given("parameter criteria as follows")]
        [StepDefinitionDescription(Documentation =
            "Supplied view select criteria.  Equivalent to entering values in Criteria pane in the Parameters portion of the GUI")]
        [OptionalColumn(Field = CriteriaLogField)]
        [OptionalColumn(Field = CriteriaOpenField)]
        [OptionalColumn(Field = CriteriaDbTableField)]
        [OptionalColumn(Field = CriteriaDbColumnField)]
        [OptionalColumn(Field = CriteriaRelField)]
        [OptionalColumn(Field = CriteriaValueField)]
        [OptionalColumn(Field = CriteriaCloseField)]
        public void GivenParameterCriteriaAsFollows(Table parameters)
        {
            var validLog = new List<string> { "and", "or" };
            var validOpen = new List<string> { "(", "((", "(((", "" };
            var validClose = new List<string> { ")", "))", ")))", "" };
            var validRel = new List<string> { "<", "<=", "<>", "=", ">", ">=", "in", "not in", "like", "not like" };
            CommonStepParameters.CheckTable(parameters);
            foreach (var row in parameters.Rows)
            {
                var log = row.GetOrDefault(CriteriaLogField, "and");
                var open = row.GetOrDefault(CriteriaOpenField, "");
                var dbTable = row.GetOrDefault(CriteriaDbTableField, "");
                var dbColumn = row.GetOrDefault(CriteriaDbColumnField, "");
                var rel = row.GetOrDefault(CriteriaRelField, "=");
                var value = row.GetOrDefault(CriteriaValueField, "");
                var close = row.GetOrDefault(CriteriaCloseField, "");
                CheckField(CriteriaLogField, log, validLog);
                CheckField(CriteriaOpenField, open, validOpen);
                CheckField(CriteriaRelField, rel, validRel);
                CheckField(CriteriaCloseField, close, validClose);

                // GUI seems to allow the table name to be omitted
                if (dbColumn == "trade" && string.IsNullOrEmpty(dbTable))
                    dbTable = "trade";

                if (dbColumn == "trade" && !int.TryParse(value, out _))
                {
                    // trade id is not a number, let's see if its a trade label
                    var id = _tradeLabelRepository.GetId(value);
                    if (!string.IsNullOrEmpty(id))
                        value = id;
                }

                if (string.IsNullOrEmpty(value))
                    StepLog.LogError("Value is required");
                _parameterRepository.AddSelectCriteria(log, open, dbTable, dbColumn, rel, value, close);
            }
        }

