[Given("parameters as follows")]
        [StepDefinitionDescription(Documentation =
            "Defines one or more parameters to control a subsequent step.  Corresponds to the 'Parameters' tab in the GUI")]
        [RequiredColumn(Field = ParameterNameField)]
        [RequiredColumn(Field = ParameterValueField)]
        public void GivenParametersAsFollows(Table parameters)
        {
            CommonStepParameters.CheckTable(parameters);
            VariableManager.ExpandTableVariables(parameters);
            var invalidParam = false;
            foreach (var row in parameters.Rows)
            {
                var value = row[ParameterValueField];
                var parameter = row[ParameterNameField];
                switch (parameter.ToLowerInvariant().Replace(" ", ""))
                {
                    case "asofdate":
                    case "as-of-date":
                        _parameterRepository.SetAsOfDate(StringConversion.StringToDateTime(value));
                        break;
                    case "acctdate":
                    case "accountdate":
                        _parameterRepository.SetAcctDate(StringConversion.StringToDateTime(value));
                        break;
                    case "creditmode":
                        _parameterRepository.SetCreditMode(value);
                        break;

                    case "checknumber":
                        _parameterRepository.SetCheckNumber(value);
                        break;
                    case "checkdate":
                        _parameterRepository.SetCheckDate(StringConversion.StringToDateTime(value));
                        break;
                    case "cashacct":
                    case "cashaccount":
                        _parameterRepository.SetCashAccount(value);
                        break;
                    case "creditvaluationmode":
                        _parameterRepository.SetCreditValuationMode(value);
                        break;
                    case "copycount":
                        _parameterRepository.SetCopyCount(value);
                        break;
                    case "cycle":
                        _parameterRepository.SetCycle(value);
                        break;
                    case "displayunit":
                        _parameterRepository.SetDisplayUnit(value);
                        break;
                    case "instrumenttype":
                        _parameterRepository.SetInstrumentType(value);
                        break;
                    case "invoicedate":
                        _parameterRepository.SetInvoiceDate(StringConversion.StringToDateTime(value));
                        break;
                    case "mtmaccrualdate":
                        _parameterRepository.SetMtMAccrualDate(StringConversion.StringToDateTime(value));
                        break;
                    case "pathbegtime":
                        _parameterRepository.SetPathBegTime(StringConversion.StringToDateTime(value));
                        break;
                    case "pathendtime":
                        _parameterRepository.SetPathEndTime(StringConversion.StringToDateTime(value));
                        break;
                    case "payor":
                        _parameterRepository.SetPayor(value);
                        break;
                    case "processtype":
                        var upperValue = value.ToUpperInvariant();
                        switch (upperValue)
                        {
                            case "CREDIT":
                            case "SETTLEMENT":
                            case "NET":
                            case "VALUATION":
                                _parameterRepository.SetProcessType(value);
                                break;
                            default:
                                StepLog.LogError($"Unrecognized Process Type '{value}'");
                                break;
                        }

                        break;
                    case "receiptdate":
                        _parameterRepository.SetReceiptDate(StringConversion.StringToDateTime(value));
                        break;
                    case "savesettlementdetail":
                        _parameterRepository.SetSaveSettlementDetail(StringConversion.StringToBool(value));
                        break;
                    case "timezone":
                        _parameterRepository.SetTimeZone(value);
                        break;
                    case "timeunit":
                        _parameterRepository.SetTimeUnit(value);
                        break;
                    case "tranqtytype":
                        _parameterRepository.SetTranQtyType(value);
                        break;
                    case "uselatestobservation":
                    case "userecentvaluationtime":
                        _parameterRepository.SetUseLatestObservation(StringConversion.StringToBool(value));
                        break;
                    case "valuationtime":
                        _parameterRepository.SetValuationTime(StringConversion.StringToDateTime(value));
                        break;
                    default:
                        StepLog.LogError($"Unrecognized parameter {parameter}");
                        invalidParam = true;
                        break;
                }
            }

            if (invalidParam)
                StepLog.LogError(
                    "Possible values : Acct Date, Cash Account, Credit Mode, Credit Valuation Mode, Display Unit, Invoice Date, MtM Accrual Date, Payor, Process Type, Receipt Date, Save Settlement Detail, Time Unit, Time Zone, Use Recent Valuation Time, Valuation Time");
        }

