        [StepDefinitionDescription(Documentation =
            "Saves a new or modified contract.  Must be followed by a check to see if the save was successful.")]
        public void WhenITryToSaveTheContract()
        {
            StepDependencies.AddDependency(TrySaveKey,
                "when I try to save the trade must be followed by a step to check the status of the ");
            TryErrorContext.SetTrying(true);
            SaveContract();
            if (StepLog.HasErrors())
                TryErrorContext.AddError(StepLog.GetErrorMessage());
        }

[Then("the contract is saved successfully")]
        public void ThenTheContractIsSavedSuccessfully()
        {
            if (TryErrorContext.HasErrors())
                StepLog.LogFatal($"contract save failed : {TryErrorContext.GetErrorMessage()}");

            StepDependencies.ClearDependency(TrySaveKey);
        }

[Then(@"the contract save fails with the message ""(.*)""")]
        [StepDefinitionDescription(
            Documentation =
                "Must be preceded by 'when I try to save the contract'"
        )]
        public void ThenTheSaveFailsWithTheMessage(string expectedErrorMessage)
        {
            expectedErrorMessage = VariableManager.ExpandVariables(expectedErrorMessage);

            if (!TryErrorContext.HasErrors())
                StepLog.LogFatal("Contract save was successful, expected failure");

            var actualErrorMessage = TryErrorContext.GetErrorMessage();
            if (!(actualErrorMessage.Contains(expectedErrorMessage) ||
                  Regex.IsMatch(actualErrorMessage, expectedErrorMessage)))
                StepLog.LogError($"Contract save failed, but with different error message : {actualErrorMessage}");

            StepDependencies.ClearDependency(TrySaveKey);
        }

