[When(@"I generate Allegro trade tests as follows")]
        [RequiredColumn(Field = FeatureMapper.TemplateColumn)]
        [OptionalColumn(Field = FeatureMapper.TestFilterColumn)]
        [OptionalColumn(Field = FeatureMapper.OutputColumn)]
        [OptionalColumn(Field = FeatureMapper.FeatureTitleColumn)]
        [OptionalColumn(Field = FeatureMapper.FeatureTagsColumn)]
        [OptionalColumnGroup(GroupName = "CommonAttributes")]
        [StepDefinitionDescription(Documentation =
            "Dynamically generates tests to create/modify trades based on the results of a previously executed query.")]
        public void WhenIGenerateAllegroTradeTestsAsFollows(Table table)
        {
            // We support a variable number of optional arguments so we can't run a proper parameter check
            // Get the target project so we know that it is valid, rather than waiting until later to discover
            DynamicGenerationContext.GetTargetProjectFile();
            var g = new FeatureMapper(DynamicGenerationContext.GetTemplateDirectories(),
                DynamicGenerationContext.GetTargetFeatureDirectory(),
                new SpecflowTradeGenerator(_customSubObjectQueries.Keys.ToList()));
            var sourceObjects = DynamicGenerationContext.HasSourceObjects()
                ? DynamicGenerationContext.GetSourceObjects()
                : CommonSelectContext.HasResults()
                    ? GetTradeInputs(CommonSelectContext.GetResults())
                    : new List<DynamicGenerationSourceObject>();
            g.GenerateFromTable(table, sourceObjects,
                DynamicGenerationContext.HasSourceObjects() || CommonSelectContext.HasResults());
        }

[When(@"I generate Allegro trade tests from query ""(.*)"" as follows")]
        [RequiredColumn(Field = FeatureMapper.TemplateColumn)]
        [OptionalColumn(Field = FeatureMapper.TestFilterColumn)]
        [OptionalColumn(Field = FeatureMapper.OutputColumn)]
        [OptionalColumn(Field = FeatureMapper.FeatureTitleColumn)]
        [OptionalColumn(Field = FeatureMapper.FeatureTagsColumn)]
        [StepDefinitionDescription(Documentation =
            "Dynamically generates tests to create/modify trades based on the results of a specified query.")]
        public void WhenIGenerateAllegroTradeTestsFromQueryAsFollows(string queryName, Table table)
        {
            var sql = QueryUtils.ReadSqlFromFile(queryName);
