[Then("the natural gas actual measurement has allocations as follows")]
        [StepDefinitionDescription(Documentation =
            "Used to check the allocations associated with a specific measurement.A single measurement must have been identified with 'Then natural gas actual measurements exist as follows'")]
        public void ThenTheNaturalGasActualMeasurementHasAllocationsAsFollows(Table table)
        {
            // find the measure if of the "parent"
            var matches = _naturalGasActualRepository.GetMatches(NaturalGasActual.NGMeasureTable);
            if (matches.Count != 1)
                StepLog.LogFatal("A single measure must be identified by a preceding steps");

            // ... then add the Measure as it were a key column.  This will ensure that we only match against allocations that related
            // to the specific measure
            var measureId =
                _naturalGasActualRepository.GetRowColumnValue(NaturalGasActual.NGMeasureTable, matches.First(),
                    "Measure");

            // TODO - add a column to a specflow table in a generic way
            var newHeaders = table.Header.ToList();
            newHeaders.Add("Measure*");
            var t = new Table(newHeaders.ToArray());

            foreach (var row in table.Rows)
            {
                var existingValues = row.Values.ToList();
                existingValues.Add(measureId);
                t.AddRow(existingValues.ToArray());
            }

            ThenIHaveNaturalGasActualAllocationsAsFollows(t);
        }

