[Then(@"the resulting MDX table is as follows")]
        public void ThenTheResultingMdxTableIsAsFollows(Table table)
        {
            var results = CubeContext.GetResults();


            if (results.Columns.Count != table.Rows[0].Count)
            {
                Assert.Fail("Inconsistent number of columns");
            }
            else if (results.Rows.Count != table.RowCount)
            {
                Assert.Fail("Inconsistent number of rows");
            }

            foreach (TableRow tableRow in table.Rows)
            {
                var match = false;

                foreach (DataRow resultsRow in results.Rows)
                {
                    var passed = true;

                    var resultsArray = resultsRow.ItemArray;
                    var tableArray = tableRow.Values.ToArray();

                    if (resultsArray[0].ToString() != tableArray[0])
                    {
                        continue;
                    }

                    for (var i = 1; i < resultsArray.Length; i++)
                    {
                        var result = double.Parse(resultsArray[i].ToString());
                        var tableResult = double.Parse(tableArray[i]);
                        if (!result.Equals(tableResult))
                        {
                            passed = false;
                        }
                    }

                    if (passed != true) continue;
                    results.Rows.Remove(resultsRow);
                    match = true;
                    break;
                }

                if (!match)
                {
                    Assert.Fail("MDX table does not match inputted table");
                }
            }
        }

[When(@"I export the MDX results with test key ""(.*)"" to a database table ""(.*)""")]
        public void WhenIExportTheMDXResultsWithTestKeyToADatabaseTable(string testKey, string dbTableName)
        {
            testKey = VariableManager.ExpandVariables(testKey);
            dbTableName = VariableManager.ExpandVariables(dbTableName);

            using (var results = CubeContext.GetResults())
            {
                var comparisonDb = new ComparisonDatabaseRepository();
                var envName = CubeContext.GetEnvironmentName();
                comparisonDb.DeleteFromTable(dbTableName, testKey, envName);

                ComparisonDatabaseRepository.AddExtraColumnValues(results,
                    ComparisonDatabaseRepository.GetCompTableColumnValues(testKey, envName));
                comparisonDb.WriteDataTableToDatabase(results, envName, dbTableName,
                    ComparisonContext.GetTableIndexes(dbTableName));
                results.Clear();

                CubeContext.SetResults(null);
            }
        }

