[Then(@"the message content should be ""(.*)""")]
        public void ThenTheMessageContentShouldBe(string expectedPattern)
        {
            var consumeResult = KafkaContext.GetCurrentConsumeResult();

            if (consumeResult == null || string.IsNullOrEmpty(consumeResult.Message.Value))
                throw new Exception("No message was consumed from Kafka.");

            // Get the actual message content
            var actualMessage = consumeResult.Message.Value;

            // Check if the actual message contains the expected pattern (instead of exact match)
            if (!actualMessage.Contains(expectedPattern))
                throw new Exception(
                    $"Message content mismatch. Expected pattern: '{expectedPattern}', but got: '{actualMessage}'.");

            Console.WriteLine($"Message content matches the expected pattern: {actualMessage}");
        }

