[Given(@"a Kafka key-value producer defined in file ""(.*)""")]
        [Given(@"a Kafka producer defined in file ""(.*)""")]
        [StepDefinitionDescription(Documentation =
            "Creates a Kafka key-value pair message producer from a specification in a file")]
        public void GivenAKafkaNameValueProducerDefinedInFile(string fileName)
        {
            try
            {
                var configuration = GetConfigFromFile(fileName);
                var configOverrides = KafkaContext.GetConfigSettings();
                foreach (var k in configOverrides.Keys)
                    configuration[k] = configuration[k];
                KafkaContext.AddNameValueProducer(new ProducerBuilder<string, string>(configuration.AsEnumerable())
                    .SetErrorHandler((p, error) =>
                        {
                            if (error.IsError)
                                StepLog.LogError($"Failed to publish - {error.Reason}");
                            else StepLog.LogToConsole($"Publish : {error.Reason}");
                        }
                    )
                    .Build());
            }
