[When(@"I publish a rabbit message from file ""(.*)"" with routing key ""(.*)""")]
        public void WhenIPublishARabbitMessageFromFileWithRoutingKey(string fileName, string routingKey)
        {
            var localPath = VariableManager.ExpandVariables(fileName);
            var fullPath = FileRepository.FindFullFilePathName(fileName);
            var body = FileRepository.ReadFileToString(fullPath);

            var repo = GetRabbitRepository();

            var props = new MessageProperties
            {
                DeliveryMode = MessageDeliveryMode.Persistent,
                ContentEncoding = "utf8"
            };

            if (fileName.EndsWith(".json"))
                props.ContentType = "application/json";
            else if (fileName.EndsWith(".xml"))
                props.ContentType = "application/xml";

            repo.Publish(routingKey, true, props, Encoding.UTF8.GetBytes(body));
        }

