[When("I unit test the try error context")]
        public void WhenIUnitTestTheTryErrorContext()
        {
            Assert.IsFalse(TryErrorContext.HasErrors(), "no errors yet");

            Assert.IsFalse(TryErrorContext.HasSuccesses(), "no successes yet");
            var errorMessage = TryErrorContext.GetErrorMessage();
            Assert.AreEqual("", errorMessage, "empty error message didn't match");
            var successMessage = TryErrorContext.GetSuccessMessage();
            Assert.AreEqual("", successMessage, "empty success message didn't match");
            TryErrorContext.AddError("some error");
            Assert.IsTrue(TryErrorContext.HasErrors(), "now there are errors");
            Assert.IsFalse(TryErrorContext.HasSuccesses(), "still no successes yet");

            TryErrorContext.AddSuccess("some success");
            Assert.IsTrue(TryErrorContext.HasSuccesses(), "now there is some success");

            errorMessage = TryErrorContext.GetErrorMessage();
            Assert.AreEqual("some error", errorMessage, "error message didn't match");

            TryErrorContext.AddError("add one more");
            errorMessage = TryErrorContext.GetErrorMessage();
            Assert.AreEqual("some error\nadd one more", errorMessage, "error message didn't match after adding error");

            successMessage = TryErrorContext.GetSuccessMessage();
            Assert.AreEqual("some success", successMessage, "success message didn't match");


            TryErrorContext.AddSuccess("add one more");
            errorMessage = TryErrorContext.GetSuccessMessage();
            Assert.AreEqual("some success\nadd one more", errorMessage,
                "success message didn't match after adding success");

            TryErrorContext.RemoveAllErrors();
            Assert.IsFalse(TryErrorContext.HasErrors(), "no errors any more");

            TryErrorContext.RemoveAllSuccesses();
            Assert.IsFalse(TryErrorContext.HasSuccesses(), "no successes any more");

            TryErrorContext.AddErrors(new[] { "one error", "and another" });
            Assert.IsTrue(TryErrorContext.HasErrors(), "now there are multiple errors");
            errorMessage = TryErrorContext.GetErrorMessage();
            Assert.AreEqual("one error\nand another", errorMessage, "error message didn't match for multiple errors");

            TryErrorContext.RemoveError("and another");
            errorMessage = TryErrorContext.GetErrorMessage();
            Assert.AreEqual("one error", errorMessage, "error message didn't match after remove");

            TryErrorContext.AddSuccesses(new[] { "one success", "and another" });
            Assert.IsTrue(TryErrorContext.HasSuccesses(), "now there are multiple Successes");
            successMessage = TryErrorContext.GetSuccessMessage();
            Assert.AreEqual("one success\nand another", successMessage,
                "success message didn't match for multiple Successes");

            TryErrorContext.RemoveSuccess("and another");
            successMessage = TryErrorContext.GetSuccessMessage();
            Assert.AreEqual("one success", successMessage, "success message didn't match after remove");

            TryErrorContext.RemoveError("removing something that doesn't exist isn't an error");
            TryErrorContext.RemoveSuccess("removing something that doesn't exist isn't an error");
        }

[When("I unit test the xml comparison context")]
        public void WhenIUnitTestTheXmlComparisonContext()
        {
            // Nothing so far
            Assert.IsFalse(XmlComparisonContext.GetPathExclusions().Any(), "no path exclusions yet");
            Assert.IsFalse(XmlComparisonContext.GetNodeExclusions().Any(), "no node exclusions yet");
            Assert.IsFalse(XmlComparisonContext.GetXmlValidationResults().Any(), "no validation results yet");
            Assert.IsTrue(XmlComparisonContext.HasValidationErrors());

            XmlComparisonContext.AddNodeContentExclusions(new List<XmlNodeExclusion>
                { new XmlNodeExclusion { NodeContents = "a", NodeName = "b" } });
            Assert.IsTrue(XmlComparisonContext.GetNodeExclusions().Any(), "now has exclusions");
            var ce = XmlComparisonContext.GetNodeExclusions();
            Assert.AreEqual(1, ce.Count, "1 exclusion");
            Assert.AreEqual("a", ce[0].NodeContents);
            Assert.AreEqual("b", ce[0].NodeName);

            XmlComparisonContext.AddNodeContentExclusions(new List<XmlNodeExclusion>
            {
                new XmlNodeExclusion { NodeContents = "c", NodeName = "d" },
                new XmlNodeExclusion { NodeContents = "e", NodeName = "f" }
            });

            Assert.AreEqual(3, ce.Count, "3 exclusions");
            Assert.AreEqual("a", ce[0].NodeContents);
            Assert.AreEqual("b", ce[0].NodeName);
            Assert.AreEqual("c", ce[1].NodeContents);
            Assert.AreEqual("d", ce[1].NodeName);
            Assert.AreEqual("e", ce[2].NodeContents);
            Assert.AreEqual("f", ce[2].NodeName);

            XmlComparisonContext.AddPathExclusions(new List<string> { "exc1" });
            Assert.IsTrue(XmlComparisonContext.GetPathExclusions().Any(), "now has path exclusions");
            var pe = XmlComparisonContext.GetPathExclusions();
            Assert.AreEqual(1, pe.Count, "1 path exclusion");
            Assert.AreEqual("exc1", pe[0]);

            XmlComparisonContext.AddPathExclusions(new List<string> { "exc2", "exc3" });
            Assert.AreEqual(3, pe.Count, "3 path exclusion");
            Assert.AreEqual("exc1", pe[0]);
            Assert.AreEqual("exc2", pe[1]);
            Assert.AreEqual("exc3", pe[2]);

            XmlComparisonContext.SetXmlValidationResults(new List<string> { "error1", "error2" });
            Assert.IsTrue(XmlComparisonContext.GetXmlValidationResults().Any(), "now has validation results");
            Assert.IsTrue(XmlComparisonContext.HasValidationErrors());
            var vr = XmlComparisonContext.GetXmlValidationResults();
            Assert.AreEqual(2, vr.Count, "2 validation results");
            Assert.AreEqual("error1", vr[0]);
            Assert.AreEqual("error2", vr[1]);
        }

