        [RequiredColumn(Field = IndexField)]
        public void GivenIUseTheFollowingIndexWhenCreatingDatabaseTable(string tableName, Table table)
        {
            tableName = VariableManager.ExpandVariables(tableName);
            VariableManager.ExpandTableVariables(table);
            CommonStepParameters.CheckTable(table);
            foreach (var row in table.Rows)
                if (!string.IsNullOrWhiteSpace(row[IndexField]))
                    ComparisonContext.AddTableIndex(tableName, row[IndexField]);
        }

