[Given("file comparison absolute numerical tolerance of (.*)")]
        [Given("a comparison absolute numerical tolerance of (.*)")]
        [StepDefinitionDescription(Documentation =
            "Two numbers are considered equal if the absolute value of their difference is less than the supplied value. Not currently supported for PDF and XML comparison.")]
        public void GivenComparisonAbsoluteNumericalToleranceOf(string absoluteTolerance)
        {
            absoluteTolerance = VariableManager.ExpandVariables(absoluteTolerance);
            if (StringConversion.TryStringToDouble(absoluteTolerance, out var tolerance))
            {
                ComparisonContext.SetDefaultAbsoluteNumericalTolerance(tolerance);
                ComparisonContext.SetCompareWithTolerance(true);
            }
            else
            {
                StepLog.LogFatal($"{absoluteTolerance} is not a valid number");
            }
        }

