[Given("file comparison absolute numerical tolerances as follows")]
        [Given("comparison absolute numerical tolerances as follows")]
        [RequiredColumn(Field = CommonFieldDefinitions.FieldName)]
        [RequiredColumn(Field = CommonFieldDefinitions.Tolerance)]
        [StepDefinitionDescription(Documentation =
            "Sets the absolute numerical tolerance for the specified fields.  If we have a tolerance of T and expected value of E, then an actual values in the range [E-T,E+T] are considered equal.  All other numerical fields use the default tolerance. Not currently supported for PDF and XML comparison..  If the specified field is not present in the files being compared then the value is ignored.")]
        public void GivenComparisonAbsoluteNumericalTolerancesAsFollows(Table table)
        {
            CommonStepParameters.CheckTable(table);
            ComparisonContext.SetCompareWithTolerance(true);
            foreach (var r in table.Rows)
            {
                var tolerance = r.GetDouble(CommonFieldDefinitions.Tolerance);
                ComparisonContext.SetFieldAbsoluteTolerance(r[CommonFieldDefinitions.FieldName], -1 * tolerance,
                    tolerance);
            }
        }

