[Given("file comparison absolute numerical tolerance ranges as follows")]
        [Given("comparison absolute numerical tolerance ranges as follows")]
        [RequiredColumn(Field = CommonFieldDefinitions.FieldName)]
        [RequiredColumn(Field = CommonFieldDefinitions.ToleranceLowerBound)]
        [RequiredColumn(Field = CommonFieldDefinitions.ToleranceUpperBound)]
        [StepDefinitionDescription(Documentation =
            "Sets the absolute numerical tolerance for the specified fields as a range.  Given a tolerance range of TL and TU and expected value of E, then an actual values in the range [E+TL,E+TU] are considered equal.  The lower tolerance bound is usually zero or a negative number and the upper tolerance bound is usually zero or a positive number. All other numerical fields use the default tolerance. If the specified field is not present in the files being compared then the value is ignored. Not currently supported for PDF and XML comparison.")]
        public void GivenComparisonAbsoluteNumericalToleranceRangesAsFollows(Table table)
        {
            CommonStepParameters.CheckTable(table);
            ComparisonContext.SetCompareWithTolerance(true);
            foreach (var r in table.Rows)
            {
                var fieldName = r[CommonFieldDefinitions.FieldName];
                var lowerBound = r.GetDouble(CommonFieldDefinitions.ToleranceLowerBound);
                var upperBound = r.GetDouble(CommonFieldDefinitions.ToleranceUpperBound);
                if (lowerBound > upperBound)
                    StepLog.LogError(
                        $"Lower bound ({lowerBound}) for {fieldName} is greater than upper bound ({upperBound})");
                else
                    ComparisonContext.SetFieldAbsoluteTolerance(fieldName, lowerBound, upperBound);
            }
        }

