        {
            if (CommonSelectContext.HasResults())
            {
                _comparisonDatabaseHelper.ExportData(CommonSelectContext.GetResults(), testKey, tableName,
                    EnvironmentContext.GetEnvironmentName());
            }
            else
            {
                var results = TabularDataComparisonContext.TryGetCurrentData(out DataTable compData)
                    ? compData == null ? new List<DataTable>() : new List<DataTable> { compData }
