[Given(@"intelligent mappings from database table ""(.*)"" with test key ""(.*)""")]
        [StepDefinitionDescription(Documentation =
            "'When I persist intelligent match results to a database table ...' persists intelligent mappings to a database.  This step reads these previously generated intelligent mappings from the specified database table/test key.  The mappings are then used in subsequent comparison.")]
        public void GivenIntelligentMappingsFromDatabaseTableWithTestKey(string tableName, string testKey)
        {
            tableName = VariableManager.ExpandVariables(tableName);
            testKey = VariableManager.ExpandVariables(testKey);
            var masterIntelligentMappings = ComparisonContext.GetMasterIntelligentMappings();
            var comparisonIntelligentMappings = ComparisonContext.GetComparisonIntelligentMappings();

            if (!_comparisonDb.Value.TableExists(tableName, MasterEnv))
                StepLog.LogFatal($"Table {tableName} does not exist in the comparison database");
            try
            {
                var sql = $"select * from [{MasterEnv}].[{tableName}] where Cmp_Label = '{testKey}'";
                using (var dt = _comparisonDb.Value.GetDataTableFromSql(sql))
                {
                    if (dt.Columns.Count != 4)
                        StepLog.LogFatal($"{tableName} is not a mapping table");

                    var mappedFieldName = dt.Columns[0].ColumnName;

                    if (!masterIntelligentMappings.ContainsKey(mappedFieldName))
                        masterIntelligentMappings[mappedFieldName] = new Dictionary<string, string>();

                    if (!comparisonIntelligentMappings.ContainsKey(mappedFieldName))
                        comparisonIntelligentMappings[mappedFieldName] = new Dictionary<string, string>();


                    foreach (DataRow row in dt.Rows)
                    {
                        var naturalKey = row[0].ToString();
                        var mapping = row[1].ToString();
                        var env = row[2].ToString();

                        if (string.Equals(env, TestEnv, StringComparison.InvariantCultureIgnoreCase))
                            comparisonIntelligentMappings[mappedFieldName][naturalKey] = mapping;
                        else if (string.Equals(env, MasterEnv, StringComparison.InvariantCultureIgnoreCase))
                            masterIntelligentMappings[mappedFieldName][naturalKey] = mapping;
                        else
                            StepLog.LogFatal(
                                $"Mapping {mapping} refers to {env} - expecting {MasterEnv} or {TestEnv}");
                    }
                }
            }
            catch (Exception e)
            {
                StepLog.LogFatal($"Failed to read intelligent mappings from {tableName} : {e.Message}");
            }
        }

[Given("intelligent mapping synonyms as follows")]
        [StepDefinitionDescription(Documentation =
            "Used if the column name(s) in an intelligent mapping are not exactly the same as the column name(s) of the data to be compared.  Supply a table with two columns - expressing the name of the column in the mapping table and the equivalent name in the data to be compared.")]
        [RequiredColumn(Field = MappingColumnNameField)]
        [RequiredColumn(Field = AlternativeColumnNameField)]
        public void GivenIntelligentMappingSynonymsAsFollows(Table columnNameMappings)
        {
            VariableManager.ExpandTableVariables(columnNameMappings);
            CommonStepParameters.CheckTable(columnNameMappings);
            var masterIntelligentMappings = ComparisonContext.GetMasterIntelligentMappings();
            var comparisonIntelligentMappings = ComparisonContext.GetComparisonIntelligentMappings();

            foreach (var row in columnNameMappings.Rows)
            {
                var mappingName = row[MappingColumnNameField];
                var alternativeName = row[AlternativeColumnNameField];
                CloneIntelligentMappings(masterIntelligentMappings, mappingName, alternativeName);
                CloneIntelligentMappings(comparisonIntelligentMappings, mappingName, alternativeName);
            }
        }

