[Then("the row mismatch errors are as follows")]
        [Then("the row differences are as follows")]
        [StepDefinitionDescription(Documentation =
            @"Asserts that the comparison has generated mismatch errors that match the supplied table.  
The table must contain all of the key columns, and 1 or more of the other non-keys columns in the master data set. 
For the non-key columns the table cell should contain either 'Yes', 'No' or be left blank.
Yes indicates the values are expected to be different.  No indicates the values are not expected to be different.  Blank indicates that either difference or no difference is acceptable.
If there are mismatch errors in addition to those supplied in the table then the step fails.  c.f. Then the row mismatch errors contain the following.")]
        public void ThenTheRowDifferencesAreAsFollows(Table expectedMisMatches)
        {
            StepDependencies.ClearDependency(TryToContext);
            IList<string> keyFields;
            var result = ComparisonResultContext.GetComparisonResult();

            // The expected mis-matches must contain either the real key or the derived one produced by intelligent matching
            if (expectedMisMatches.ContainsColumn(DataTableComparer.DerivedKey))
            {
                if (!result.ComparisonColumnNames.Contains(DataTableComparer.DerivedKey) ||
                    !result.MasterColumnNames.Contains(DataTableComparer.DerivedKey))
                    StepLog.LogError(
                        $"{DataTableComparer.DerivedKey} not present in comparison results.  Non intelligent match?");
                keyFields = new List<string> { DataTableComparer.DerivedKey };
            }
            else
            {
                foreach (var f in result.KeyFields)
                    if (!expectedMisMatches.Header.Contains(f))
                        StepLog.LogError($"key field '{f}' must be specified in the table");
                keyFields = result.KeyFields;
            }

            foreach (var h in expectedMisMatches.Header)
                if (!result.MasterColumnNames.Contains(h) &&
                    !CommonFieldDefinitions.AllTestCommentFields.Contains(h))
                    StepLog.LogError($"Column '{h}' is not a valid column name in the comparison results");

            if (!StepLog.HasErrors())
            {
                var actualErrors = result.Differences.OfType<RowPairDifference>().ToList();

                // We have errors and expectations of errors. the test will fail if
                // (a) there errors which were not expected
                // (b) there were expectations of errors that were not met
                var metExpectations = new Dictionary<string, List<string>>();

                // get all the differences for each row
                foreach (var differencesForRow in actualErrors)
                {
                    // try to find exactly one row in the specflow table that matches this error
                    var matchingRows = expectedMisMatches.Rows.Select(r => r);

                    var primaryKeyValues = new List<string>();

                    // Construct a string representation and find the rows that match it
                    foreach (var k in keyFields)
                    {
                        primaryKeyValues.Add($"{k}={differencesForRow.MasterValue[k]}");
                        matchingRows =
                            matchingRows.Where(r => r[k] == differencesForRow.MasterValue[k].ToString());
                    }

                    var keyStr = string.Join(",", primaryKeyValues);

                    // We should have precisely one match
                    if (!matchingRows.Any())
                    {
                        // We had errors, but nothing in the specflow table says they are expected
                        StepLog.LogError($"Row mismatch errors present for {keyStr}");
                    }
                    else if (matchingRows.Count() > 1)
                    {
                        // We seem to have multiple rows in the specflow table for the same unique row in the master/comparison data sets
                        StepLog.LogError(
                            $"Ambiguous expected results for {keyStr}.  Primary key should appear only once in expected results.");
                    }
                    else
                    {
                        // Now we need to go through each column where there is a difference and see if it was expected or not
                        // by definition differences can only appear in non-key fields (we matched on key fields before we compared
                        // if key fields didn't match the errors appear as master/comparison has extras, not mismatch)
                        var matchingRow = matchingRows.First();
                        // we have errors for a row, and we have expectations about which are expected/unexpected/don't care
                        foreach (var mmc in differencesForRow.DifferingColumns)
                        {
                            var colName = result.MasterColumnNames[mmc];

                            if (!expectedMisMatches.ContainsColumn(colName) ||
                                matchingRow[colName].ToLower() == "no")
                            {
                                // We have a mismatch, but it is not expected
                                StepLog.LogError(
                                    $"Unexpected difference for {keyStr} '{colName}' : {differencesForRow.MasterValue[mmc]} vs {differencesForRow.ComparisonValue[mmc]}");
                            }
                            else if (expectedMisMatches.ContainsColumn(colName)
                                     && (string.IsNullOrEmpty(matchingRow[colName]) ||
                                         matchingRow[colName].ToLower() == "yes" ||
                                         matchingRow[colName] == "*"))
                            {
                                // all good - we expected an error and it appeared
                                if (!metExpectations.ContainsKey(keyStr))
                                    metExpectations[keyStr] = new List<string>();

                                // record the fact
                                metExpectations[keyStr].Add(colName);
                            }
                            else
                            {
                                StepLog.LogError(
                                    $"{keyStr}: unrecognised value {matchingRow[colName]} for '{colName}' : Yes =  difference expected, No = difference not expected, blank = don't care");
                            }
                        }
                    }
                }

                // Now make a second pass to see if any of the expected differences did not materialize
                foreach (var row in expectedMisMatches.Rows)
                {
                    var primaryKeyValues = new List<string>();
                    foreach (var k in keyFields) primaryKeyValues.Add($"{k}={row[k]}");

                    var keyStr = string.Join(",", primaryKeyValues);

                    foreach (var nonKeyField in expectedMisMatches.Header.Where(h => !keyFields.Contains(h)
                                 && !CommonFieldDefinitions.AllTestCommentFields.Contains(h)))
                        if (row[nonKeyField].ToLowerInvariant() == "yes")
                            if (!metExpectations.ContainsKey(keyStr) ||
                                metExpectations[keyStr].All(f => f != nonKeyField))
                                StepLog.LogError(
                                    $"Expected difference for {keyStr} did not appear: '{nonKeyField}' ");
                }
            }
        }

