[Then("there are no comparison differences")]
        [Then("the comparison is successful")]
        [Then("the comparison succeeds")]
        [StepDefinitionDescription(Documentation =
            "Asserts that there are no differences between master (expected) and comparison (actual) data sets, or no difference remaining after accepting known differences")]
        public void ThenThereAreNoComparisonDifferences()
        {
            var result = ComparisonResultContext.GetComparisonResult();

            StepDependencies.ClearDependency(TryToContext);

            if (!result.Success || result.Differences.Any())
            {
                if (result.Differences.Any())
                {
                    if (ComparisonContext.HasDifferencesFile())
                    {
                        var outputFile = ComparisonContext.GetDifferencesFile();
                        FileReportingContext.AddFile("Differences", outputFile);
                        StepLog.LogFatal(
                            $"Differences detected : See {FileRepository.GetFileUrl(outputFile)}");
                    }
                    else
                    {
                        foreach (var cd in result.Differences.OfType<ColumnDifference>())
                            StepLog.LogError($"{cd.Error}");
                        var n = result.Differences.OfType<RowPairDifference>().Count();
                        if (n > 0)
                            StepLog.LogError($"{n} mis-matched rows");
                        n = result.Differences.OfType<ExtraRowDifference>().Count(d => d.IsMaster);
                        if (n > 0)
                            StepLog.LogError($"Master has {n} extra rows");
                        n = result.Differences.OfType<ExtraRowDifference>().Count(d => !d.IsMaster);
                        if (n > 0)
                            StepLog.LogError($"Comparison has {n} extra rows");
                        n = result.Differences.OfType<MissingExpectedExtraRowDifference>().Count(d => d.IsMaster);
                        if (n > 0)
                            StepLog.LogError($"{n} expected rows were not present in Master");
                        n = result.Differences.OfType<MissingExpectedExtraRowDifference>().Count(d => !d.IsMaster);
                        if (n > 0)
                            StepLog.LogError($"{n} expected rows were not present in Comparison");
                    }
                }

                StepLog.LogFatal("Comparison failed");
            }
        }

