[Given(
            @"I retrieve equivalence mapping using SQL file ""(.*)"" and test key ""(.*)"" and environment ""(.*)""")]
        [Given(
            @"I retrieve equivalence mapping using sql file ""(.*)"" and test key ""(.*)"" and environment ""(.*)""")]
        [StepDefinitionDescription(Documentation =
            "Runs the specified SQL statement which is expected to returns rows with two columns.  The first column contains the identifiers (primary key) for some objects (trades, documents, files, etc) in the master environment  and the second column contains the equivalent identifier from the other (comparison) environment.  This equivalence mapping can be used in subsequent comparison.")]
        public void GivenIRetrieveEquivalenceMappingUsingSQLFile(string fileName, string testKey,
            string environmentName)
        {
            fileName = VariableManager.ExpandVariables(fileName);
            testKey = VariableManager.ExpandVariables(testKey);
            environmentName = VariableManager.ExpandVariables(environmentName);

            var sql = GetSqlFromFile(fileName);
            using (var dt = _comparisonDb.Value.GetDataTableFromSql(sql, testKey, environmentName))
            {
                if (dt.Columns.Count != 2)
                    StepLog.LogError("SQL is expected to return two columns - expected and equivalent actual");
                if (dt.Columns.Count > 0 && dt.Columns[0].DataType != typeof(string))
                    StepLog.LogError("First column should be of type string");
                if (dt.Columns.Count > 1 && dt.Columns[1].DataType != typeof(string))
                    StepLog.LogError("Second column should be of type string");

                if (!StepLog.HasErrors())
                    foreach (DataRow row in dt.Rows)
                        FileComparisonContext.AddEquivalenceMapping((string)row[0], (string)row[1]);
            }
        }

