[Given(@"a direct connection to database ""(.*)""")]
        [StepDefinitionDescription(
            Documentation =
                "Connects to a database as specified in DatabaseEnvironmentsSection of app.config"
        )]
        public void GivenADirectConnectionToDatabase(string name)
        {
            name = VariableManager.ExpandVariables(name);
            var environments = EnvironmentRepository.GetDatabaseEnvironments();
            var env = environments.FirstOrDefault(d =>
                string.Equals(d.EnvironmentName, name, StringComparison.InvariantCultureIgnoreCase));
            if (env != null)
            {
                if (string.IsNullOrWhiteSpace(env.DBType)) StepLog.LogFatal("DBType must be specified");
                if (string.IsNullOrWhiteSpace(env.DBConnString)) StepLog.LogFatal("DBConnString must be specified");
                if (string.Equals(env.DBType.Trim(), "Oracle", StringComparison.InvariantCultureIgnoreCase))
                    Database.ConnectTo(DatabaseType.Oracle, env.DBConnString);
                else if (string.Equals(env.DBType.Trim(), "SqlServer", StringComparison.InvariantCultureIgnoreCase))
                    Database.ConnectTo(DatabaseType.SqlServer, env.DBConnString);
                else StepLog.LogFatal($"Unsupported DB type {env.DBType}.  Must be Oracle or SqlServer");
                EnvironmentContext.SetEnvironmentName(name);
            }
            else
            {
                var envNames = string.Join(",", environments.Select(e => e.EnvironmentName));
                StepLog.LogFatal($"Unrecognised environment {name}.  Possible environment names: {envNames}");
            }
        }

