[When(@"I export the direct SQL select results with test key ""(.*)"" to a database table ""(.*)""")]
        [When(@"I export the SQL select results with test key ""(.*)"" to a database table ""(.*)""")]
        [When(@"I export the direct SQL select statement results with test key ""(.*)"" to a database table ""(.*)""")]
        [When(@"I export the SQL select statement results with test key ""(.*)"" to a database table ""(.*)""")]
        public void WhenIExportTheDirectSelectResultsWithTestKeyToADatabaseTable(string testKey, string dbTableName)
        {
            testKey = VariableManager.ExpandVariables(testKey);
            dbTableName = VariableManager.ExpandVariables(dbTableName);

            var results = CommonSelectContext.GetResults();
            var comparisonDb = new ComparisonDatabaseRepository();
            var envName = EnvironmentContext.GetEnvironmentName();
            comparisonDb.DeleteFromTable(dbTableName, testKey, envName);

            var extraCols = ComparisonDatabaseRepository.GetCompTableColumnValues(testKey, envName);
            ComparisonDatabaseRepository.AddExtraColumnValues(results, extraCols);

            comparisonDb.WriteDataTableToDatabase(results, envName, dbTableName,
                ComparisonContext.GetTableIndexes(dbTableName));

            // Remove any columns we added, in case we have a subsequent step that wants to export the results
            // e.g. if exporting to database and spreadsheet
            foreach (var ec in extraCols)
                results.Columns.Remove(ec.ColumnName);
        }

