[RequiredColumn(Field = CommonFieldDefinitions.Pattern)]
        [OptionalColumn(Field = CommonFieldDefinitions.Replacement)]
        [When("I perform search and replace on the file as follows")]
        [When("I perform search and replace on the files as follows")]
        [StepDefinitionDescription(Documentation =
            "Searches for occurrences of a pattern within files and replaces them with the specified value. The pattern/replacement can be simple text, or a regular expression.  Note that the file is updated 'in place'.  If you wish to preserve the original file then use steps to copy the originals to a separate directory before performing the search/replace.  Suitable for text, csv and xml files.  Not suitable for, for example, xlsx and pdf files.  Replacement text can be omitted, in which case text matching the pattern is simply removed (replaced by an empty string)")]
        public void WhenIPerformRegexSearchAndReplaceOnTheFileAsFollows(Table table)
        {
            VariableManager.ExpandTableVariables(table);
            CommonStepParameters.CheckTable(table);

            var files = new List<string>();
            if (FileComparisonContext.HasActualFiles())
                files.AddRange(FileComparisonContext.GetActualFiles());
            if (FileComparisonContext.HasExpectedFiles())
                files.AddRange(FileComparisonContext.GetExpectedFiles());

            if (FileContext.HasFile())
                files.Add(FileContext.GetFileName());

            if (!files.Any())
                StepLog.LogFatal("No files identified");

            foreach (var file in files)
            {
                var fi = new FileInfo(file);
                if (!fi.Exists)
                {
                    StepLog.LogError($"{file} does not exist");
                    continue;
                }

                var allText =
                    FileRepository.ReadAllText(fi.FullName, FileComparisonContext.GetExclusiveAccessForRead());
                var modified = false;
                foreach (var tableRow in table.Rows)
                {
                    var regex = tableRow[CommonFieldDefinitions.Pattern];
                    var replacement = tableRow.GetOrDefault(CommonFieldDefinitions.Replacement, "");

                    try
                    {
                        if (Regex.IsMatch(allText, regex))
                        {
                            allText = Regex.Replace(allText, regex, replacement);
                            modified = true;
                        }
                    }
                    catch (Exception e)
                    {
                        StepLog.LogError($"Failed to perform substitution on {file} : {e.Message}");
                    }
                }

                if (modified)
                {
                    File.WriteAllText(fi.FullName, allText);
                }
            }
        }

