[Given("I exclude from comparison the following columns")]
        [Given("I ignore the following columns")]
        [OptionalColumn(Field = "Sheet Name")]
        [RequiredColumn(Field = CommonFieldDefinitions.ColumnNameField)]
        [StepDefinitionDescription(
            Documentation =
                "Specifies columns to be ignored for the purposes of file comparison.  If comparing spreadsheets with multiple sheets you can specify in which sheet the columns are found.  If Column Name is '*' then all columns are ignored in the specified sheet"
        )]
        public void GivenIExcludeFromComparisonTheFollowingColumns(Table table)
        {
            VariableManager.ExpandTableVariables(table);
            CommonStepParameters.CheckTable(table);
            foreach (var row in table.Rows)
            {
                var colName = row.GetString(CommonFieldDefinitions.ColumnNameField);
                if (String.IsNullOrWhiteSpace(colName))
                    continue;
                var sheetName = row.GetOrDefault("Sheet Name", "*");
                ComparisonContext.AddIgnoredColumn(sheetName, colName);
            }
        }

