[When("I compare the files")]
        [StepDefinitionDescription(Documentation =
            "Compares (two / two sets of) files. Fails if differences are detected")]
        public void WhenICompareTheFiles()
            => CompareFiles(GetFileComparer());

[When("I try to compare the files")]
        [StepDefinitionDescription(Documentation =
            "Compares (two / two sets of) files. The step does not fail if the files are different. Must be followed by a subsequent step to assert whether or not the comparison was successful.  Can be used as part of a test to assert that files are expected to be different.")]
        public void WhenITryToCompareTheFiles()
            =>
                CompareFiles(GetFileComparer(), true);

[Given("file reading is performed with variable expansion")]
        [StepDefinitionDescription(Documentation =
            "This step will set the variable expansion to true, if you add this given step before copying a file then any variables present in the files will be replaced by variable values")]
        public void GivenFileReadingIsPerformedWithVariableExpansion()
            => TriangleScenarioContext.Set(true, IsVariableExpand);

[Given(@"a file called ""(.*)"" does not exist")]
        [Then(@"a file called ""(.*)"" does not exist")]
        [StepDefinitionDescription(Documentation = "Asserts that the specified file does not exist.")]
        public void ThenAFileCalledDoesNotExist(string fileName)
        {
            fileName = VariableManager.ExpandVariables(fileName);
            var exists = FileRepository.TryFindFullFilePathName(fileName, out var fullFilePath, out var ambiguous);

            if (exists)
                StepLog.LogError($"File does exist : {fullFilePath}");
            else if (ambiguous)
                StepLog.LogError("Multiple files match the supplied pattern");
        }

[Given(@"a file called ""(.*)"" does not exist")]
        [Then(@"a file called ""(.*)"" does not exist")]
        [StepDefinitionDescription(Documentation = "Asserts that the specified file does not exist.")]
        public void ThenAFileCalledDoesNotExist(string fileName)
        {
            fileName = VariableManager.ExpandVariables(fileName);
            var exists = FileRepository.TryFindFullFilePathName(fileName, out var fullFilePath, out var ambiguous);

            if (exists)
                StepLog.LogError($"File does exist : {fullFilePath}");
            else if (ambiguous)
                StepLog.LogError("Multiple files match the supplied pattern");
        }

[Given("the following files do not exist")]
        [Then("the following files do not exist")]
        [RequiredColumn(Field = FileName)]
        [StepDefinitionDescription(Documentation = "Asserts that the specified files do not exist.")]
        public void ThenAFileCalledDoesNotExist(Table files)
        {
            VariableManager.ExpandTableVariables(files);
            CommonStepParameters.CheckTable(files);

            foreach (var row in files.Rows)
                if (FileRepository.TryFindFullFilePathName(row[FileName], out _))
