        public void WhenICopyFile(string sourceFileName, string destFile)
        {
            destFile = VariableManager.ExpandVariables(destFile);
            sourceFileName = VariableManager.ExpandVariables(sourceFileName);
            var fullFilePath = FileRepository.FindFullFilePathName(sourceFileName);

            string tempFile = null;
            if (TriangleScenarioContext.ContainsKey(IsVariableExpand))
                tempFile = VariableManager.ExpandFileContentVariables(fullFilePath,
                    FileComparisonContext.GetExclusiveAccessForRead());

            FileRepository.CopyFileToFile(tempFile ?? fullFilePath, destFile);

            if (tempFile != null)
                File.Delete(tempFile);
        }

