[When(@"I lock a file called ""(.*)""")]
        [StepDefinitionDescription(Documentation =
            "Creates a write lock on the specified file.  Creates an empty file if the file does not exist.  The lock is held for the duration of the scenario.")]
        public void WhenILockAFileCalled(string filePath)
        {
            filePath = VariableManager.ExpandVariables(filePath);
            try
            {
                if (FileRepository.TryFindFullFilePathName(filePath, out var fullFilePath))
                {
                    var fs = new FileStream(fullFilePath, FileMode.Append, FileAccess.Write);
                    FileContext.AddOpenFile(fs);
                }
                else
                {
                    File.Create(filePath);
                    var fs = new FileStream(filePath, FileMode.Append, FileAccess.Write);
                    FileContext.AddOpenFile(fs);
                }
            }
            catch (Exception e)
            {
                StepLog.LogFatal($"Failed to lock {filePath}: {e.Message}");
            }
        }

