[When("I amend the JSON object as follows")]
        [RequiredColumn(Field = FieldName)]
        [RequiredColumn(Field = FieldValue)]
        [StepDefinitionDescription(Documentation = "Amends a previously specified JSON object.")]
        public void WhenIAmendTheJSONAsFollows(Table table)
        {
            CommonStepParameters.CheckTable(table);
            VariableManager.ExpandTableVariables(table);
            var jsonObj = JsonContext.GetJsonToken();

            foreach (var row in table.Rows)
            {
                var path = row[FieldName];
                var value = row[FieldValue];
                try
                {
                    foreach (var t in jsonObj.SelectTokens(path))
                        if (t != null)
                            switch (t.Type)
                            {
                                case JTokenType.Integer:
                                    if (StringConversion.TryStringToInt(value, out var i))
                                        t.Replace(i);
                                    else StepLog.LogError($"cannot set integer property {path} to {value}");

                                    break;

                                case JTokenType.Float:
                                    if (StringConversion.TryStringToDouble(value, out var f))
                                        t.Replace(f);
                                    else StepLog.LogError($"cannot set floating point property {path} to {value}");
                                    break;

                                case JTokenType.Boolean:
                                    if (StringConversion.TryStringToBool(value, out var b))
                                        t.Replace(b);
                                    else StepLog.LogError($"cannot set boolean property {path} to {value}");
                                    break;

                                case JTokenType.Guid:
                                    if (Guid.TryParse(value, out var g))
                                        t.Replace(g);
                                    else StepLog.LogError($"cannot set GUID property {path} to {value}");
                                    break;

                                case JTokenType.TimeSpan:
                                    if (TimeSpan.TryParse(value, out var ts))
                                        t.Replace(ts);
                                    else StepLog.LogError($"cannot set time span property {path} to {value}");
                                    break;

                                default:
                                    t.Replace(value);
                                    break;
                            }
                }
                catch (Exception e)
                {
                    StepLog.LogError($"{path} does not refer to valid field in the JSON object : {e.Message}");
                }
            }
        }

