[Given(@"I skip subsequent steps if variable ""(.*)"" is not set")]
        [StepDefinitionDescription(Documentation =
            "Checks if a variable has been set, either in App.Config or on the command line when running from nunit console runner.  If the variable has not been set to any (non-empty) then the current scenario is marked as ignored and no further steps are run")]
        public void GivenISkipSubsequentStepsIfCategoryIsNotSet(string variable)
        {
            variable = VariableManager.ExpandVariables(variable);
            var value = ConfigSettings.GetSetting(variable);
            if (String.IsNullOrEmpty(value) && !VariableContext.GetScenarioVariables().ContainsKey(variable))
                Skip($"{variable} is not set, so skipping subsequent steps");
        }

[Given(@"I skip subsequent steps if variable ""(.*)"" is set")]
        [StepDefinitionDescription(Documentation =
            "Checks if a variable has been set, either in App.Config or on the command line when running from nunit console runner.  If the variable has any (non-empty) value then the current scenario is marked as ignored and no further steps are run")]
        public void GivenISkipSubsequentStepsIfCategoryIsSet(string variable)
        {
            variable = VariableManager.ExpandVariables(variable);
            var value = ConfigSettings.GetSetting(variable);
            if (!String.IsNullOrEmpty(value))
                Skip($"{variable} is set to '{value}', so skipping subsequent steps");
            if (VariableContext.GetScenarioVariables().TryGetValue(variable, out var vv))
                Skip($"{variable} is set to '{vv}', so skipping subsequent steps");
        }

