[Given(@"a maximum test execution time of ""(.*)"" seconds")]
        [StepDefinitionDescription(Documentation =
            "Will cause the test to fail at the point it exceeds the specified time")]
        public void GivenAMaximumTestExecutionTimeOfSeconds(string maxTimeInSeconds)
        {
            maxTimeInSeconds = VariableManager.ExpandVariables(maxTimeInSeconds);
            if (StringConversion.TryStringToDouble(maxTimeInSeconds, out var maxTime))
            {
                var cts = new CancellationTokenSource();
                ThreadPool.QueueUserWorkItem(new WaitCallback(func => AbortAfter(maxTime, cts.Token)));
                TimingContext.SetTimerThread(cts);
            }
            else StepLog.LogFatal($"Invalid maximum test execution time {maxTimeInSeconds}");
        }

[Then(@"the test completes in less than ""(.*)""")]
        [StepDefinitionDescription(Documentation =
            "Asserts that scenario has taken less than the specified time period (hh:mm:ss).  Typically, but not necessarily, the last step in a scenario.  Note that this does not put a limit on how a test will actually take, it simply reports as a failure if the test takes more than the specified time. c.f. Given a maximum test execution time of xx seconds.")]
        public void GivenTheTestCompletesInLessThan(string timespan)
        {
            var elapsed = DateTime.Now.ToUniversalTime() -
                          TestExecutionContext.CurrentContext.StartTime.ToUniversalTime();
            if (elapsed > TimeSpan.Parse(timespan))
                StepLog.LogFatal(
                    $"Exceeded the maximum test duration of '{timespan}'. Actual test duration was '{elapsed}' ");
            StepLog.LogToConsole($"Test duration was '{elapsed}'");
        }

[Then(@"the test completes in less than ""(.*)"" seconds")]
        public void ThenTheTestCompletesInLessThanSeconds(string seconds)
        {
            var numSeconds = StringConversion.StringToDouble(VariableManager.ExpandVariables(seconds));

            var elapsed = DateTime.Now.ToUniversalTime() -
                          TestExecutionContext.CurrentContext.StartTime.ToUniversalTime();
            if (elapsed.TotalSeconds > numSeconds)
                StepLog.LogFatal(
                    $"Exceeded the maximum test duration of {numSeconds} seconds. Actual test duration was {elapsed.TotalSeconds} seconds ");
            StepLog.LogToConsole($"(est duration was '{elapsed.TotalSeconds} seconds");
        }

