[Given("the following HTTP headers")]
        [RequiredColumn(Field = CommonFieldDefinitions.VariableName)]
        [RequiredColumn(Field = CommonFieldDefinitions.Value)]
        public void GivenTheFollowingHTTPHeaders(Table headers)
        {
            VariableManager.ExpandTableVariables(headers);
            CommonStepParameters.CheckTable(headers);
            foreach (var row in headers.Rows)
            {
                var setting = row[CommonFieldDefinitions.VariableName];
                var value = row[CommonFieldDefinitions.Value];
                var matchingHeaderSetting = _headerMappings.Keys.FirstOrDefault(k =>
                    k.Equals(setting, StringComparison.InvariantCultureIgnoreCase));
                if (matchingHeaderSetting != null)
                    WebServiceContext.SetHttpRequestHeaderField(matchingHeaderSetting, value);
                else
                    WebServiceContext.SetHttpRequestHeaderField(setting, value);
            }
        }

