[Then("the HTTP response contains the following headers")]
        [RequiredColumn(Field = CommonFieldDefinitions.VariableName)]
        [RequiredColumn(Field = CommonFieldDefinitions.Value)]
        public void ThenTheHTTPResponseContainsTheFollowingHeaders(Table expectedHeaders)
        {
            VariableManager.ExpandTableVariables(expectedHeaders);
            CommonStepParameters.CheckTable(expectedHeaders);
            var responseHeaders = WebServiceContext.GetHttpResponse().Headers;
            var h = new Dictionary<string, string>();
            foreach (string k in responseHeaders.Keys)
                h[k] = responseHeaders[k];

            foreach (var row in expectedHeaders.Rows)
            {
                var headerName = row[CommonFieldDefinitions.VariableName];
                var expectedValue = row[CommonFieldDefinitions.Value];
                var headerValue = h.Keys.FirstOrDefault(k => string.Equals(k, headerName,
                    StringComparison.InvariantCultureIgnoreCase));
                if (headerValue == null)
                {
                    StepLog.LogError($"No such header {headerName}");
                }
                else
                {
                    var actualValue = h[headerValue];
                    if (!string.Equals(actualValue, expectedValue))
                        StepLog.LogError($"Expected {expectedValue}.  Actual {actualValue}");
                }
            }
        }

