[When(@"I make a ""(.*)"" HTTP request")]
        [StepDefinitionDescription(Documentation =
            "This step executes a previously defined request using the specified HTTP method.")]
        public void WhenIMakeAHttpRequestMethod(string method)
        {
            _webClient.Execute(method);

            // regardless of content type header, attempt to parse content as Json and, if successful, store in context thus making immediately available for next step
            try
            {
                var t = JToken.Parse(_webClient.ResponseContent);
                JsonContext.AddJsonToken(t);
                return;
            }
            catch (Exception)
            {
                ;
            }

            // regardless of content type header, attempt to parse content as Xml and, if successful, store in context thus making immediately available for next step
            try
            {
                var xmlDoc = new XmlDocument();
                xmlDoc.LoadXml(_webClient.ResponseContent);
                XmlContext.AddXmlDocument(xmlDoc);
            }
            catch (Exception)
            {
                ;
            }
        }

