[Given("the XML document has elements as follows")]
        [Then("the XML document has elements as follows")]
        [StepDefinitionDescription(Documentation =
            "Checks the current XML document in memory.  The parts of the document to check are defined by an xPath expression.  If the xPath expression matches multiple all elements then all must match the specified value.  If the xPath expression does not match any elements then this is  considered an error. Must be preceded by 'Given an XML file'")]
        [RequiredColumn(Field = PathField)]
        [RequiredColumn(Field = ValueField)]
        public void GivenTheXMLDocumentHasElementsAsFollows(Table table)
        {
            CommonStepParameters.CheckTable(table);
            VariableManager.ExpandTableVariables(table);
            var doc = XmlContext.GetXmlDocument();

            // The heading can include optional information about numerical tolerance
            var valueColumn = table.GetColumnHeadings().First(h => h.Heading == ValueField);
            foreach (var row in table.Rows)
            {
                var xPath = row[PathField];
                var expectedValue = row[valueColumn.RawHeading];
                var matchingNodes = GetMatchingNodes(doc, xPath);
                if (matchingNodes != null && matchingNodes.Count > 0)
                    // iterate through the elements and check them
                    foreach (XmlNode node in matchingNodes)
                    {
                        var actualValue = node.InnerText;
                        // TODO - need to check what type of node?
                        _fieldComparer.Compare(xPath, actualValue, expectedValue, valueColumn);
                    }
                else
                    StepLog.LogError($"{xPath} does not match any elements");
            }
        }

