[When(@"I apply the XSLT file ""(.*)"" to the following XML files")]
        [RequiredColumn(Field = XmlFile)]
        [RequiredColumn(Field = OutputFile)]
        [StepDefinitionDescription(Documentation =
            "Applies the specified XSL transform to one or more files.  If an output file is not specified the source files are transformed in-place.")]
        public void WhenIApplyTheXsltFileToTheFollowingXmlFiles(string xsltFile, Table xmlPaths)
        {
            CommonStepParameters.CheckTable(xmlPaths);
            xsltFile = VariableManager.ExpandVariables(xsltFile);
            VariableManager.ExpandTableVariables(xmlPaths);
            foreach (var row in xmlPaths.Rows)
            {
                var xmlPath = row[XmlFile];

                var fullFileName = FileRepository.FindFullFilePathName(xmlPath);

                var xml = new XPathDocument(fullFileName);
                var xslt = new XslCompiledTransform();

                var xsltPath = Path.Combine(FileRepository.GetDirectoryName(Assembly.GetExecutingAssembly().Location),
                    xsltFile);

                xslt.Load(xsltPath);
                var outputPath = row.GetOrDefault(OutputFile, fullFileName);
                FileRepository.CreateDirectoryIfNecessary(outputPath);

                var outputStream = new XmlTextWriter(outputPath, null);

                xslt.Transform(xml, null, outputStream);
            }
        }

[When(@"I validate the xml against the schema ""(.*)""")]
