            "Validates all files within the file comparison context against an .xsd.")]
        public void WhenIValidateTheXmlFileAgainstTheSchema(string xsdPath)
        {
            var expandedXsdPath = VariableManager.ExpandVariables(xsdPath);
            var actualFiles = FileComparisonContext.GetActualFiles().Select(f => new FileInfo(f)).ToList();
            foreach (var actualFile in actualFiles)
                WhenIValidateTheXmlFileAgainstTheSchema(actualFile.FullName, expandedXsdPath);

            if (XmlComparisonContext.HasValidationErrors())
            {
                var validationErrors =
                    XmlComparisonContext.GetXmlValidationResults();
                StepLog.LogFatal($"XML Validation failed: {string.Join("\n", string.Join("\n", validationErrors))}");
