        }

[When(@"I validate the XML file ""(.*)"" against the schema ""(.*)""")]
        public void WhenIValidateTheXmlFileAgainstTheSchema(string xmlPath, string xsdPath)
        {
            xmlPath = VariableManager.ExpandVariables(xmlPath);
            xsdPath = VariableManager.ExpandVariables(xsdPath);
            if (!File.Exists(xmlPath)) StepLog.LogError($"XML file does not exist: '{xmlPath}'");
            if (!File.Exists(xsdPath)) StepLog.LogError($"XSD file does not exist: '{xsdPath}'");

            if (StepLog.HasErrors())
                return;

            var doc = XDocument.Load(xmlPath);
            var schema = new XmlSchemaSet();
            schema.Add(null, xsdPath);
            var validationEventHandler = new ValidationEventHandler(XmlValidationErrorHandler);

            doc.Validate(schema, validationEventHandler);
        }

