[When(@"I open APM page ""(.*)"" and output to ""(.*)""")]
        [StepDefinitionDescription(
            Documentation =
                "Opens an APM page and renders the results as a csv file."
        )]
        public void WhenIOpenAPMPage(string page, string output)
        {
            var inputFile = page.EndsWith(".ppg") ? page : $"{page}.ppg";
            var outputFile = output.EndsWith(".csv") ? output : $"{output}.csv";

            var fullOutputPath = VariableManager.ExpandVariables(outputFile);
            var fullPagePath = VariableManager.ExpandVariables(inputFile);

            if (!fullPagePath.StartsWith("/User"))
            {
                // Only do this if the file is on the file server.  If the file begins /User
                // then it is probably stored in the Endur directory service.  APM console
                // knows how to receive these files
                fullPagePath = FileRepository.FindFullFilePathName(fullPagePath);
                if (!File.Exists(fullPagePath))
                    StepLog.LogFatal($"File {fullPagePath} does not exist");

                fullPagePath = Path.GetFullPath(fullPagePath);
            }



            FileRepository.CreateDirectoryIfNecessary(fullOutputPath);
            File.Delete(fullOutputPath);
            var logFileName = fullOutputPath.Replace(".csv", "-log.txt");
            File.Delete(logFileName);

            string temporaryConfigFile = BuildConfigFile(fullPagePath, fullOutputPath);

            var workingDirectory = Path.Combine(OpenlinkInitialiser.OlfBinDir, "apm");

            var olfEnvironment = OpenlinkConfig.GetExternalSystemWideConfigDictionary();
            var exe = Path.Combine(workingDirectory, "ApmConsole.exe");
            if (!File.Exists(exe))
                StepLog.LogFatal($"Cannot find APM Console : {exe}");

            var cmd = new ExternalCommand($"\"{exe}\"",
                $"-reports -batch \" {temporaryConfigFile} \" -log \" {logFileName} \"",
                workingDirectory);
            cmd.Run(olfEnvironment);

            if (!File.Exists(fullOutputPath))
                StepLog.LogFatal("Failed to generate APM output");

            File.Delete(temporaryConfigFile);
        }

