[Given(@"I wait until a document of type ""(.*)"" exists for transaction ""(.*)""")]
        [StepDefinitionDescription(Documentation =
            "Waits until a document exists (at any status) of a given type for a transaction identified by test label.  Succeeds immediately if the document already exists.  See the steps under 'Step Repeat (Common)' for an explanation on how to control the frequency and maximum number of retries.")]
