[Given(@"I wait until a document of type ""(.*)"" exists at status ""(.*)"" for transaction ""(.*)""")]
        [StepDefinitionDescription(Documentation =
            "Waits until a document exists of a given type/status for a transaction identified by test label.  Succeeds immediately if the document exists and is already at that status.  See the steps under 'Step Repeat (Common)' for an explanation on how to control the frequency and maximum number of retries.")]
        public void WhenIWaitUntilADocumentOfTypeExistsAtStatusForTransaction(string documentationType,
            string documentationStatus, string testLabel)
        {
            documentationType = VariableManager.ExpandVariables(documentationType);
            documentationStatus = VariableManager.ExpandVariables(documentationStatus);
            testLabel = TestLabel.Expand(testLabel);
            ValidateDocumentType(documentationType);
            if (!documentationStatus.Contains("%"))
                ValidateStatus(documentationStatus);

            if (!TryGetTransactionByTestLabel(testLabel, out _))
                StepLog.LogFatal($"No transaction with test label {testLabel} exists");

            RepeaterFactory.Repeater.RepeatUntil(() =>
                {
                    var sql = $@"select h.document_num from stldoc_header h
                                inner join stldoc_details sd on h.document_num = sd.document_num
                                inner join {SpecflowRefMapFields.TransactionRefMapTable} m on m.deal_num = sd.deal_tracking_num
                                inner join ab_tran ab on ab.deal_tracking_num = sd.deal_tracking_num and ab.current_flag = 1
                                inner join stldoc_document_status ds on h.doc_status = ds.doc_status
                                inner join stldoc_document_type dt on h.doc_type = dt.doc_type
                                where 
                                            m.test_label = '{testLabel}' 
                                       and dt.doc_type_desc = '{documentationType}' 
                                       and ds.doc_status_desc like '{documentationStatus}'";

                    var results = SqlRunner.RunSqlToInts(sql);
                    foreach (var docNum in results)
                        DocumentContext.AddDocumentToContext(
                            _backOfficeRepository.Value.GetDocumentById(docNum));

                    return results.Any();
                },
                "Abandoned wait. Document does not exist.");
        }

