[When(@"I generate a document for definition ""(.*)"" with additional data as follows")]
        [When(@"I generate documents for definition ""(.*)"" with additional data as follows")]
        [StepDefinitionDescription(
            Documentation =
                "Generates one or more documents for the given definition.  The events to process must have previously identified by running a settlement events query.  The events are supplemented with additional data provided in the table")]
        public void WhenIGenerateTheDocumentForTheDefinitionWithOverrides(string definition, Table additions)
        {
            if (additions.RowCount != 1)
                StepLog.LogFatal("Additional data currently assumed to be a single row that applies to all events.  Support for filtering to be added later");
            VariableManager.ExpandTableVariables(additions);
            definition = VariableManager.ExpandVariables(definition);
            var et = GetEventTable();
            var at = EndurTableConverter.Value.SpecflowToOlfTable(additions,
                EndurTableRepository.Value.CreateTable("additions"));
            Response.LogResponse(et);
            Response.LogResponse(at);
            if (!StepLog.HasErrors())
            {
                var numEvents = EndurTableRepository.Value.GetTableRowCount(et);
                StepLog.LogToConsole($"Query returned {numEvents} events");
                if (numEvents == 0)
                    return;

                foreach (var columnName in EndurTableRepository.Value.GetColumnNames(at))
                {
                    var columnType = EndurTableRepository.Value.GetColumnType(at, columnName);
                    EndurTableRepository.Value.AddColumn(et, columnName, columnType);
                    for (var i = 0; i < numEvents; i++)
                        switch (columnType)
                        {
                            case EnumTTLColType.Int:
                                Response.LogResponse(EndurTableRepository.Value.SetInt(et, columnName, i,
                                    EndurTableRepository.Value.GetValueAsInteger(at, columnName, 0)));
                                break;
                            case EnumTTLColType.Double:
                                Response.LogResponse(EndurTableRepository.Value.SetDouble(et, columnName, i,
                                    EndurTableRepository.Value.GetValueAsDouble(at, columnName, 0)));
                                break;
                            case EnumTTLColType.DateTime:
                                Response.LogResponse(EndurTableRepository.Value.SetDate(et, columnName, i,
                                    EndurTableRepository.Value.GetValueAsDateTime(at, columnName, 0).DateTime));
                                break;
                            default:
                            case EnumTTLColType.String:
                                Response.LogResponse(EndurTableRepository.Value.SetString(et, columnName, i,
                                    EndurTableRepository.Value.GetValueAsString(at, columnName, 0)));
                                break;
                        }
                }

                GenerateDocs(definition, () => _backOfficeRepository.Value.GenerateDocumentsFromTable(definition, et));
            }
        }

