[When(@"I retrieve documents using SQL ""(.*)""")]
        [StepDefinitionDescription(
            Documentation = "Retrieves a document using the supplied SQL query")]
        public void WhenIRetrieveDocumentsUsingSQL(string query)
        {
            query = VariableManager.ExpandVariables(query);
            var table = RunSqlToTable(query);

            if (table.ColumnCount != 1)
                StepLog.LogFatal("SQL should return a single column - containing document numbers");
            if (table.RowCount == 0) StepLog.LogFatal("No matching documents were found");
            if (ConfigSettings.IsFlagEnabled(TraceFlag))
                StepLog.LogToConsole($"SQL returned {table.RowCount} rows");

            for (var i = 0; i < table.RowCount; i++)
            {
                var docNum = table.GetRow(i).GetColumnValueAsInteger(0);
                var doc = _backOfficeRepository.Value.GetDocumentById(docNum);
                Response.LogResponse(doc);
                if (doc.Response.Success)
                {
                    if (doc.None) StepLog.LogError($"No document exists with the document number {docNum}");
                    else if (doc.Ambiguous)
                        StepLog.LogError($"More than one document with the document number {docNum}!");
                    else
                        DocumentContext.AddDocumentToContext(doc);
                }
            }
        }

