[RequiredColumn(Field = CommonOpenlinkFields.TestLabel)]
        [RequiredColumn(Field = DocumentFieldDefinitions.Status)]
        [Then("the current documents are at statuses")]
        [Given("the documents are at statuses as follows")]
        [Then("the documents are at statuses as follows")]
        [StepDefinitionDescription(
            Documentation =
                "Asserts that the previously specified set of documents are at the given statuses"
        )]
        public void ThenTheCurrentDocumentsAreAtStatuses(Table table)
        {
            OpenlinkStepParameters.CheckTable(table);
            VariableManager.ExpandTableVariables(table);

            foreach (var tableRow in table.Rows)
            {
                var label = TestLabel.Expand(tableRow[CommonOpenlinkFields.TestLabel]);
                if (!TryGetDocumentByTestLabel(label, out var doc))
                {
                    StepLog.LogError($"Unknown document label {label}");
                    continue;
                }

                var expectedStatus = tableRow[DocumentFieldDefinitions.Status];
                var actualStatus = GetDocumentStatus(doc.DocNum);
                if (expectedStatus != actualStatus)
                    StepLog.LogError(
                        $"Status for document {doc.TestLabel}/{doc.DocNum} is '{actualStatus}', expected '{expectedStatus}'");
            }
        }

