[When(@"I successfully move the document to status ""(.*)""")]
        [When(@"I successfully move the documents to status ""(.*)""")]
        [When(@"I move the document to status ""(.*)""")]
        [When(@"I move the documents to status ""(.*)""")]
        [StepDefinitionDescription(
            Documentation =
                "Moves the previously specified document(s) to the status.  The step fails if one or more of the document moves is not possible, but not before trying to move all documents.  Contrast with 'when I try to move the document ...'"
        )]
        public void WhenISuccessfullyMoveTheDocumentToStatus(string status)
        {
            status = VariableManager.ExpandVariables(status);
            ValidateStatus(status);
            var docs = DocumentContext.GetMultipleDocumentsFromContext();
            foreach (var doc in docs)
                try
                {
                    if (ConfigSettings.IsFlagEnabled(TraceFlag))
                        StepLog.LogToConsole($"Moving {doc.DocNum} {doc.TestLabel ?? ""} to '{status}'");
                    var response =
                        _backOfficeRepository.Value.MoveDocumentToStatus(doc, status, DocumentContext.GetStpOverride());
                    Response.LogResponse(response);
                }
                catch (Exception e)
                {
                    StepLog.LogError(
                        $"Document {doc.DocNum} was not successfully moved to status '{status}': {e.Message}");
                }

            if (!StepLog.HasErrors())
            {
                if (ConfigSettings.IsFlagEnabled(TraceFlag))
                    StepLog.LogToConsole("re-querying for latest document status");

                var docCopy = new List<TTLDocumentHandle>(docs);
                foreach (var doc in docCopy)
                    DocumentContext.RemoveDocumentFromContext(doc);
                foreach (var dn in docCopy)
                    DocumentContext.AddDocumentToContext(_backOfficeRepository.Value.GetDocumentById(dn.DocNum));
            }
        }

