[When(@"I try to move the document to status ""(.*)""")]
        [StepDefinitionDescription(
            Documentation =
                "Tries to move the previously specified document to the status.  If the move fails, this step will still succeed but the error message is kept and can be checked with 'the document move fails with the message...'"
        )]
        public void WhenITryToMoveTheDocumentToStatus(string status)
        {
            status = VariableManager.ExpandVariables(status);
            var docHandle = DocumentContext.GetSingleDocumentFromContext();
            ValidateStatus(status);
            var newDoc =
                _backOfficeRepository.Value.TryMoveDocumentToStatus(docHandle, status,
                    DocumentContext.GetStpOverride());

            if (!newDoc.Response.Success)
            {
                TriangleScenarioContext.Set(string.Join("\n", newDoc.Response.Messages.Select(m => m.Message)),
                    DocStatusMoveFailMsg);
            }
            else
            {
                TriangleScenarioContext.Set(string.Empty, DocStatusMoveFailMsg);
                DocumentContext.RemoveDocumentFromContext(docHandle);
                DocumentContext.AddDocumentToContext(newDoc);
            }

            StepDependencies.AddDependency("try to move doc",
                "'When I try to move the document to status' should be followed by either 'the document move fails with the message ..' or 'the document is at status ..'");
        }

[Then(@"the document move fails with the message ""(.*)""")]
        [StepDefinitionDescription(
            Documentation =
                "Must be preceded by 'when I try to move the document to status xxx'"
        )]
        public void ThenTheDocumentMoveFailsWithTheMessage(string expectedErrorMessage)
        {
            expectedErrorMessage = VariableManager.ExpandVariables(expectedErrorMessage);
            var actualErrorMessage =
                TriangleScenarioContext.GetOrError<string>(DocStatusMoveFailMsg,
                    "Document try move step hasn't executed");

            if (string.IsNullOrEmpty(actualErrorMessage))
                StepLog.LogFatal("Document move was successful, expected failure");

            // ReSharper disable once PossibleNullReferenceException
            if (!(actualErrorMessage.Contains(expectedErrorMessage) ||
                  Regex.IsMatch(actualErrorMessage, expectedErrorMessage)))
                StepLog.LogError($"Document move failed, but with different error message : {actualErrorMessage}");

            StepDependencies.ClearDependency("try to move doc");
        }

