[When(@"I move the document indirectly to status ""(.*)""")]
        [StepDefinitionDescription(
            Documentation =
                "Tries to move a document to a specified status whilst entering the fewest intermediary statuses")]
        public void WhenIMoveTheDocumentIndirectlyToStatus(string targetStatus)
        {
            targetStatus = VariableManager.ExpandVariables(targetStatus);
            // Get the document
            var doc = DocumentContext.GetSingleDocumentFromContext();
            // Find out the doc type and status
            var currentStatus = GetDocumentStatus(doc.DocNum);
            var docType = GetDocumentType(doc.DocNum);
            var moves = FindDocumentMovePath(docType, currentStatus, targetStatus);

            if (!moves.Any())
            {
                if (currentStatus == targetStatus)
                    StepLog.LogToConsole($"Document already at {targetStatus}");
                else
                    StepLog.LogError($"No move from {currentStatus} to {targetStatus} for {docType} document");
                return;
            }

            foreach (var m in moves)
            {
                StepLog.LogToConsole($"Move {doc.DocNum} from {currentStatus} to {m}");

                var newDoc = _backOfficeRepository.Value.MoveDocumentToStatus(doc, m, DocumentContext.GetStpOverride());
                currentStatus = GetDocumentStatus(doc.DocNum);

                if (newDoc.Response.Success)
                {
                    DocumentContext.RemoveDocumentFromContext(doc);
                    DocumentContext.AddDocumentToContext(newDoc);
                }

                // Sometimes we get an error, but the document move has occurred.
                if (currentStatus == m)
                    newDoc.Response = new TTLResponse { Success = true };

                Response.LogResponse(newDoc);
                if (!newDoc.Response.Success)
                    StepLog.LogFatal($"Failed to move document {doc.DocNum} from '{currentStatus}' to '{m}'");
            }
        }

