[OptionalColumn(Field = DocumentFieldDefinitions.IsDefault)]
        [RequiredColumn(Field = DocumentFieldDefinitions.FromStatus)]
        [RequiredColumn(Field = DocumentFieldDefinitions.ToStatus)]
        [Given(@"document transitions for document type ""(.*)"" exist as follows")]
        [When(@"document transitions for document type ""(.*)"" exist as follows")]
        [StepDefinitionDescription(
            Documentation =
                "Asserts that document transitions (moves from one status to another) are possible for a given document type")]
        public void GivenDocumentTransitionsForDocumentTypeExistAsFollows(string docType, Table expectedTransitions)
        {
            docType = VariableManager.ExpandVariables(docType);
            ValidateDocumentType(docType);
            VariableManager.ExpandTableVariables(expectedTransitions);
            OpenlinkStepParameters.CheckTable(expectedTransitions);
            var sql = $@"
                select  s.doc_status_desc as ""{DocumentFieldDefinitions.FromStatus}""
                        , y.doc_status_desc as ""{DocumentFieldDefinitions.ToStatus}""
                        , ny.name as ""{DocumentFieldDefinitions.IsDefault}""
                    from stldoc_document_status s
                    inner join stldoc_document_workflow w on s.doc_status = w.doc_status
                    inner join stldoc_document_status y on y.doc_status = w.next_doc_status
                    inner join stldoc_document_type t on  t.doc_type = w.doc_type
                    inner join no_yes ny on ny.id_number = w.default_flag
                        where t.doc_type_desc = '{docType}'
            ";

            RunSqlAndCompare(sql, expectedTransitions, CompareType.Contains);
        }

