        [When(@"I export the generation data as XML to directory ""(.*)""")]
        [StepDefinitionDescription(
            Documentation =
                "Exports the generation data as XML files for currently identified documents to the specified directory. If the documents have been labelled the file name is <test label>.xml, otherwise it is <document number>.xml")]
        public void WhenIExportTheGenerationOutputDataTableAsXmlToADirectoryCalled(string directory)
        {
            directory = VariableManager.ExpandVariables(directory);
            Directory.CreateDirectory(directory);

            var docs = DocumentContext.GetMultipleDocumentsFromContext();
            foreach (var doc in docs)
            {
                var fileName = doc.TestLabel ?? "";
                if (string.IsNullOrWhiteSpace(doc.TestLabel))
                {
                    var sql =
                        $"select test_label from {SpecflowRefMapFields.DocumentRefMapTable} where doc_num = {doc.DocNum} order by 1";
                    var results = EndurDatabaseRepository.Value.RunSqlToStrings(sql);
                    fileName = !results.Any() ? $"{doc.DocNum}" : results.First();
                }

                fileName = fileName.Replace(":", "_")
                    .Replace("\\", "_").Replace("/", "_");

                var filePath = Path.Combine(directory, $"{fileName}.xml");
                TryToExportAsXML(doc, filePath);
            }
        }

