[Given("the following STP exceptions exist")]
        [RequiredColumn(Field = DocumentFieldDefinitions.StpRuleName)]
        [RequiredColumn(Field = DocumentFieldDefinitions.DocumentNum)]
        [RequiredColumn(Field = DocumentFieldDefinitions.EventNum)]
        public void GivenTheFollowingSTPExceptionsExist(Table expectedHits)
        {
            OpenlinkStepParameters.CheckTable(expectedHits);
            VariableManager.ExpandTableVariables(expectedHits);
            foreach (var r in expectedHits.Rows)
            {
                var eventNum = r.GetLong(DocumentFieldDefinitions.EventNum);
                var docNum = r.GetInt(DocumentFieldDefinitions.DocumentNum);
                var ruleName = r.GetString(DocumentFieldDefinitions.StpRuleName);
                var sql = $@"select seh.hit_id
                                from stp_exception_hit seh
                                inner join stp_exception ex on seh.rule_id = ex.rule_id
                                where event_num = {eventNum} 
                                  and seh.document_num = {docNum} 
                                  and ex.rule_name = '{ruleName}'";
                var hitIds = SqlRunner.RunSqlToLongs(sql);
                if (!hitIds.Any())
                    StepLog.LogError($"No hits for rule {ruleName} for event {eventNum} of document {docNum}");
                else DocumentContext.AddStpHits(hitIds);
            }
        }

