[When(@"I import a CMM file ""(.*)""")]
        [StepDefinitionDescription(Documentation = "Imports the specified CMM file ")]
        public void WhenIImportACMMFile(string filename)
        {
            filename = VariableManager.ExpandVariables(filename);
            // Although we don't need an Endur session here, it initializes toolkit and loads dlls 
            // which we do depend upon
            RepositoryFactory.GetEndurSession();
            var fullFilePath = FileRepository.FindFullFilePathName(filename);
            var normalizedPath = Path.GetFullPath(new Uri(fullFilePath).LocalPath);

            string relocatedDir = null;
            if (normalizedPath.Length > ConfigSettings.GetSettingOrDefault("CMM.MaxPath", 250))
            {
                relocatedDir = FileRepository.GetTempDirName();
                StepLog.LogWarning($"Path name too long.  Copying to temp dir {relocatedDir}");
                Directory.CreateDirectory(relocatedDir);
                var newFileName = Path.Combine(relocatedDir, Path.GetFileName(normalizedPath));
                var subDirectoryName = Path.GetFileName(normalizedPath).Replace(".manifest.xml", "");
                var subDirectory = Path.Combine(Path.GetDirectoryName(normalizedPath), subDirectoryName);
                StepLog.LogWarning($"Relocating CMM files from {subDirectory}");
                File.Copy(normalizedPath, newFileName);
                FileRepository.CloneDirectory(subDirectory, Path.Combine(relocatedDir, subDirectoryName));
                normalizedPath = newFileName;
            }

            StepLog.LogDebug($"Importing from {normalizedPath}");
            var response = _cmmRepository.Value.ImportCMMFile(normalizedPath);
            Response.LogResponse(response);

            if (relocatedDir != null) FileRepository.DeleteDirectory(relocatedDir);
        }

