        [OptionalColumn(Field = TradingDateAutoRoll)]
        [OptionalColumn(Field = ProcessingDateAutoRoll)]
        [OptionalColumn(Field = EODDateAutoRoll)]
        public void GivenAutoRollConfigAsFollows(Table configTable)
        {
            CommonStepParameters.CheckTable(configTable);
            var sql =
                $@"SELECT CASE WHEN business_date_autoroll = 1 THEN 'true' ELSE 'false' END as '{BusinessDateAutoRoll}',
                                CASE WHEN trading_date_autoroll = 1 THEN 'true' ELSE 'false' END as '{TradingDateAutoRoll}',
                                CASE WHEN processing_date_autoroll = 1 THEN 'true' ELSE 'false' END as '{ProcessingDateAutoRoll}',
                                CASE WHEN eod_date_autoroll = 1 THEN 'true' ELSE 'false' END as '{EODDateAutoRoll}'
                               FROM auto_roll_config";
            RunSqlAndCompare(sql, configTable, CompareType.ExactMatch);
        }

