[When(@"I run the Endur SQL select statement in AFS file ""(.*)""")]
        [When(@"I run the Findur SQL select statement in AFS file ""(.*)""")]
        [StepDefinitionDescription(
            Documentation =
                "Reads a SQL statement from the specified AFS file and runs it via the Endur/Findur session."
        )]
        public void WhenIRunTheEndurSQLSelectStatementInAFSFile(string afsFileName)
        {
            RepositoryFactory.GetEndurSession();
            afsFileName = VariableManager.ExpandVariables(afsFileName);
            var th = EndurTableRepository.Value.GetAfsTable(afsFileName);
            Response.LogResponse(th);
            if (th.Response.Success)
            {
                var t = new TTLOlfTable(EndurTableRepository.Value, th);
                if (t.ColumnCount != 1)
                    StepLog.LogError($"Table has {t.ColumnCount} columns : expected 1");
                if (t.RowCount != 1)
                    StepLog.LogError($"Table has {t.RowCount} rows : expected 1");
                if (!StepLog.HasErrors())
                {
                    CommonSelectContext.SetSql(t.GetRow(0).GetColumnValueAsString(0));
                    WhenIRunTheEndurSqlSelectStatement();
                }
            }
        }

