[RequiredColumn(Field = TransactionFieldDefinitions.CommodityLocation)]
        [OptionalColumn(Field = NomDetailsFieldDefinitions.AssetBalance)]
        [OptionalColumn(Field = NomDetailsFieldDefinitions.RecAvailqty)]
        [OptionalColumn(Field = NomDetailsFieldDefinitions.DelAvailqty)]
        [Then("gas pool assets are as follows")]
        public void ThenGasPoolAssetsAreAsFollows(Table pAssetTbl)
        {
            VariableManager.ExpandTableVariables(pAssetTbl);
            OpenlinkStepParameters.CheckTable(pAssetTbl);
            
            var queryCriteria = SchedulingContext.GetNomQueryCriteria();
            var sqlGasDate = TTLDateUtil.ToDatabaseDate(Session.Value.GetDatabaseType(), queryCriteria.FlowDay.ToDateTime());
            
            var locList = pAssetTbl.Rows.Select(row => row.GetString($"{TransactionFieldDefinitions.CommodityLocation}*")).ToList();
            var pipelineId = _referenceDataRepository.Value.NameToId(EnumTTLReferenceTable.GasPhysPipeline,
                queryCriteria.ServiceProvider);

            var sql = $@"select gpl.location_name location,  
                               SUM(csd.receipt_quantity) AS balance,
                               SUM(csd.receipt_quantity) AS rec_available_qty,
                               -- delivery available qty is always 0
                               0 AS del_available_qty
                               from comm_schedule_delivery csd
                               inner join gas_phys_location gpl on csd.delivery_location_id = gpl.location_id
                               inner join gas_phys_loc_type gplt on gpl.location_type = gplt.loc_type_id 
                               where csd.start_date_time = {sqlGasDate}
                               AND csd.pipeline_id = {pipelineId}
                               and gpl.active = 1 and gplt.loc_type_pool_flag = 1 
                               and gpl.location_name in ({string.Join(", ", locList.Select(x => $"'{x}'"))})
                               group by gpl.location_name";
            
            var actualPoolBalance = EndurDatabaseRepository.Value.RunSql(sql);
            _nomQueryResTableComparer.Compare(CompareType.Contains, pAssetTbl, actualPoolBalance);
        }

[RequiredColumn(Field = CommonOpenlinkFields.TransactionTestLabel)]
        [OptionalColumn(Field = NomDetailsFieldDefinitions.AssetBalance)]
        [OptionalColumn(Field = NomDetailsFieldDefinitions.RecAvailqty)]
        [OptionalColumn(Field = NomDetailsFieldDefinitions.DelAvailqty)]
        [Then("gas storage assets are as follows")]
        public void ThenGasStorageAssetsAreAsFollows(Table sAssetTbl)
        {
            VariableManager.ExpandTableVariables(sAssetTbl);
            OpenlinkStepParameters.CheckTable(sAssetTbl);
        
            //Convert test label to deal num
            foreach (var row in sAssetTbl.Rows)
            {
                row[CommonOpenlinkFields.TransactionTestLabel] = _fieldManager.Value.GetDealNumFromTestLabel(row[CommonOpenlinkFields.TransactionTestLabel]).ToString();
            }
            
            //rename column
            sAssetTbl.RenameColumn(CommonOpenlinkFields.TransactionTestLabel, "deal_tracking_num*");
            
            var queryCriteria = SchedulingContext.GetNomQueryCriteria();
            var sqlGasDate = TTLDateUtil.ToDatabaseDate(Session.Value.GetDatabaseType(), queryCriteria.FlowDay.ToDateTime());
            var pipelineId = _referenceDataRepository.Value.NameToId(EnumTTLReferenceTable.GasPhysPipeline,
                queryCriteria.ServiceProvider);

            var sql = $@"SELECT ph.contract_number contract, ab.deal_tracking_num,
                             csb.sched_balance AS balance,
                             csb.sched_balance AS rec_available_qty,
                             0 AS del_available_qty
                             from ab_tran ab
                             inner join phys_header ph on ab.ins_num = ph.ins_num
                             inner join comm_storage_balance csb on ab.ins_num = csb.ins_num
                             where  ab.tran_status in (2, 3) 
                             and ab.current_flag = 1 
                             and csb.volume_date = {sqlGasDate} 
                             AND ph.pipeline_id = {pipelineId}";
            
            var actualStorageBalance = EndurDatabaseRepository.Value.RunSql(sql);
            _nomQueryResTableComparer.Compare(CompareType.Contains, sAssetTbl, actualStorageBalance);
        }

