        { 
            var nominationHandles = ProcessGasNomination();
            if (nominationHandles.Count > 1) // new noms created when nom is processed
            {
                // get min deal num (first nom booked is the original nom)  
                var minNomId = nominationHandles.Min(x => x.Id);
                
                //loop through new noms only
                foreach (var nominationHandle in nominationHandles.Where(n => n.Id != minNomId))
                {
                    var originalTestLabel = _testLabelRepository.GetLabelFromId(EnumSchedulingObjectType.Nomination, minNomId);
                    var newTestLabel = "";
                    
                    // get suffix if set 
                    var testLabelSuffix = SchedulingContext.GetNomTestLabelSuffix();
                    if (testLabelSuffix.Any())
                    {
                        newTestLabel = $"{originalTestLabel}-{testLabelSuffix.First()}";
                    }
                    //else use default orignialNomtestlabel-startdate-enddate
                    else
                    {
                        var nomStartDate = _schedulingRepository.Value.GetNominationFieldValueAsString(nominationHandle,
                            (int)EnumTTLNominationField.NominationStartDate);
                        var nomStartDateFormatted = StringConversion.StringToDateTime(nomStartDate).ToString("yyyyddMM");
                    
                        var nomEndDate = _schedulingRepository.Value.GetNominationFieldValueAsString(nominationHandle,
                            (int)EnumTTLNominationField.NominationEndDate);
                        var nomEndDateFormatted = StringConversion.StringToDateTime(nomEndDate).ToString("yyyyddMM");

                    
                        newTestLabel = $"{originalTestLabel}-{nomStartDateFormatted}-{nomEndDateFormatted}";
                    }
                    
                    _testLabelRepository.SaveTestLabel(EnumSchedulingObjectType.Nomination, nominationHandle.Id, newTestLabel);
                    StepLog.LogToConsole($"Saved nomination {nominationHandle.Id} with test label '{newTestLabel}'");
                }
            }
        }

