[RequiredColumnsWithChoice(GroupName = nameof(ColumnGroups.NomQtyMgmtPageControl) )]
        [RequiredColumn(Field = SchedulingFieldDefinitions.NominationDailyVolumeType)]
        [OptionalColumnGroup(GroupName = nameof(ColumnGroups.NomQtyMgmtPageControlOptional))]
        [When("I refresh gas nomination quantity management page as follows")]
        public void WhenIRefreshGasNominationQuantityManagementPageAsFollows(Table qmQuery)
        {
            OpenlinkStepParameters.CheckTable(qmQuery,1);
            VariableManager.ExpandTableVariables(qmQuery);

            var row = qmQuery.Rows[0];
            var qmTTLQuery = new TTLQtyManagementQuery
            {
                VolumeType = GasSchedulingVolumeTypeEnum(row[SchedulingFieldDefinitions.NominationDailyVolumeType])
            };

            // if contains nom test label then we are looking for a single nomination
            if(qmQuery.ContainsColumn(NomDetailsFieldDefinitions.NomTestLabel))
            {
                var nominationId = TestLabelRepository.GetIdFromLabel(EnumSchedulingObjectType.Nomination, row[NomDetailsFieldDefinitions.NomTestLabel]);
                qmTTLQuery.NominationTestLabel = row[NomDetailsFieldDefinitions.NomTestLabel];
                qmTTLQuery.DeliveryId = nominationId;
            }
            else
            {
                qmTTLQuery.ServiceProvider = row[SchedulingFieldDefinitions.ServiceProvider];
                qmTTLQuery.Contract =
                    qmQuery.ContainsColumn(SchedulingFieldDefinitions.NominationServiceProviderContractId)
                        ? GetContractId(row[SchedulingFieldDefinitions.NominationServiceProviderContractId])
                        : 0;
                qmTTLQuery.ExtParty = qmQuery.ContainsColumn(NomDetailsFieldDefinitions.QtyMgmtExtParty) ? row[NomDetailsFieldDefinitions.QtyMgmtExtParty] : null;
                qmTTLQuery.Location = qmQuery.ContainsColumn(SchedulingFieldDefinitions.Location) ? row[SchedulingFieldDefinitions.Location] : null;
                qmTTLQuery.DealNum = qmQuery.ContainsColumn(SchedulingFieldDefinitions.Location) 
                    ? TestLabelRepository.GetIdFromLabel(row[CommonOpenlinkFields.TransactionTestLabel])
                    : 0;
                qmTTLQuery.GasDayStart = qmQuery.ContainsColumn(NomDetailsFieldDefinitions.QtyMgmtGasDayStart) 
                    ? StringConversion.StringToDateTime(row[NomDetailsFieldDefinitions.QtyMgmtGasDayStart]).ToTTLDateTime()
                    : null;
                qmTTLQuery.GasDayEnd= qmQuery.ContainsColumn(NomDetailsFieldDefinitions.QtyMgmtGasDayEnd) 
                    ? StringConversion.StringToDateTime(row[NomDetailsFieldDefinitions.QtyMgmtGasDayEnd]).ToTTLDateTime()
                    : null;
            }

            var qmRes = ExecuteQtyMgmtQuery(qmTTLQuery);
            SchedulingContext.AddGasNomQtyMgmtTable(qmRes);
        }

