[RequiredColumn(Field = TransactionFieldDefinitions.HistFXRateDate)]
        [RequiredColumnsWithChoice(GroupName = nameof(ColumnGroups.FxBidMidOffer))]
        [When(@"I add the following historical FX rates for the currency ""(.*)""")]
        [When(
            @"I amend the following historical FX rates for the currency ""([^\\""]*)"" and reference currency ""(.*)"" ")]
        [StepDefinitionDescription(
            Documentation =
                "Inserts historical FX rates for the specified currency against the FX base currency.  If rates already exist they are replaced by the supplied values.  Note the rates are stored immediately; no separate save step is required."
        )]
        public void WhenIAddTheFollowingHistoricalFXRatesForTheCurrency(string currencyCode, Table requiredRates)
        {
            currencyCode = VariableManager.ExpandVariables(currencyCode);
            OpenlinkStepParameters.CheckTable(requiredRates);
            VariableManager.ExpandTableVariables(requiredRates);
            var rates = new List<TTLHistoricalFxRate>();
            foreach (var row in requiredRates.Rows)
            {
                var r = new TTLHistoricalFxRate
                {
                    FxRateDate = row.GetDate(TransactionFieldDefinitions.HistFXRateDate).ToTTLDateTime(),
                    Bid = double.NaN,
                    Offer = double.NaN
                };
                if (row.ContainsKey(TransactionFieldDefinitions.HistFXRateMid))
                {
                    r.Bid = row.GetDouble(TransactionFieldDefinitions.HistFXRateMid);
                    r.Offer = row.GetDouble(TransactionFieldDefinitions.HistFXRateMid);
                }

                if (row.ContainsKey(TransactionFieldDefinitions.HistFXRateBid))
                    r.Bid = row.GetDouble(TransactionFieldDefinitions.HistFXRateBid);
                if (row.ContainsKey(TransactionFieldDefinitions.HistFXRateOffer))
                    r.Offer = row.GetDouble(TransactionFieldDefinitions.HistFXRateOffer);

                rates.Add(r);
            }

            Response.LogResponse(MarketDataRepository.Value.SaveHistoricalFxRates(currencyCode, rates));
        }

