[Given(@"I retrieve indexes of type ""(.*)""")]
        [When(@"I retrieve indexes of type ""(.*)""")]
        [StepDefinitionDescription(Documentation =
            "retries indexes of the specified type.  No operation is performed on the indexes, but this step defines the scope of subsequent steps in this scenario.")]
        public void GivenIndexesOfTypeExists(string indexType)
        {
            indexType = VariableManager.ExpandVariables(indexType);

            var key = CurveInfo.Keys.FirstOrDefault(k =>
                string.Equals(k, indexType, StringComparison.InvariantCultureIgnoreCase));
            if (key == null)
                StepLog.LogFatal(
                    $"Unrecognized index type '{indexType}'.  Possible values : {string.Join(",", CurveInfo.Keys)}");
            else
            {
                var indexes = MarketDataRepository.Value.GetIndexesByType(CurveInfo[key].IndexType).ToList();
                Response.LogResponse(indexes);
                IndexContext.AddIndexesToContext(indexes);
            }
        }

