[When("I change the index grid point prices as follows")]
        [When("I update the index grid point prices as follows")]
        [When("I amend the index grid point prices as follows")]
        [When("I enter the index grid point prices as follows")]
        [OptionalColumn(Field = IndexGridPointFields.IndexGridPointName)]
        [OptionalColumn(Field = IndexGridPointFields.IndexGridPointLabel)]
        [OptionalColumn(Field = IndexGridPointFields.IndexGridPointInputLabel)]
        [RequiredColumn(Field = IndexGridPointFields.IndexGridPointInputValue)]
        [StepDefinitionDescription(
            Documentation =
                "Modifies the grid point prices as identified by grid point name or label.  The grid point name can either be a literal name (e.g. O/N, 1m, 2m, etc) or regular expression (e.g. \\dm).  Note that the changes are for the current session only, unless explicitly saved to universal or closing data sets. The value on the grid point to update defaults to 'input' if not specified."
        )]
        public void WhenIChangeTheIndexGridPointPricesAsFollows(Table table)
        {
            VariableManager.ExpandTableVariables(table);
            OpenlinkStepParameters.CheckTable(table);

            if (!table.ContainsColumn(IndexGridPointFields.IndexGridPointName)
                && !table.ContainsColumn(IndexGridPointFields.IndexGridPointLabel))
                StepLog.LogFatal($"Either {IndexGridPointFields.IndexGridPointName} or {IndexGridPointFields.IndexGridPointLabel} must be specified");

            foreach (var idx in IndexContext.GetMultipleIndexesFromContext())
            {
                foreach (var row in table.Rows)
                {
                    var gridPointLabel = row.GetOrDefault(IndexGridPointFields.IndexGridPointLabel, "");
                    var gridPointName = row.GetOrDefault(IndexGridPointFields.IndexGridPointName, "");
                    var price = row[IndexGridPointFields.IndexGridPointInputValue];
                    var fieldLabel = row.GetOrDefault(IndexGridPointFields.IndexGridPointInputLabel, "input");

                    // Technically * is not a valid regular expression, but we support it as a synonym for .*
                    if (gridPointLabel == "*")
                        gridPointLabel = ".*";
                    if (gridPointName == "*")
                        gridPointName = ".*";


                    var gridPoints = GetMatchingGridPoints(idx, gridPointLabel, gridPointName);

                    if (!gridPoints.Any())
                    {
                        var activeGridPoints = MarketDataRepository.Value.GetActiveGridPointsForIndex(idx);
                        var errorMessage = $"Index '{idx.Name}: no grid points found for label '{gridPointLabel}'\n" +
                                           $"Available grid points for index '{idx.Name}':\n {string.Join(" ", activeGridPoints.Select(x=> $"{x.Label}/{x.Name}" ))}";
                        if (IndexContext.GetMissingGridPointIsError())
                        {
                            StepLog.LogFatal(errorMessage);
                        }
                        else
                        {
                            StepLog.LogWarning(errorMessage);
                        }

                    }
                    else
                    {
                        // TODO - might be better to pass grid point ids.
                        Response.LogResponse(MarketDataRepository.Value.ChangeIndexGridPointPrices(idx, gridPoints.Select(gp=> gp.Name).ToList(),
                            fieldLabel,
                            price));
                    }
                }
            }
        }

