[When(@"I load close for dataset ""([^""]*)"" for ""([^""]*)""")]
        [StepDefinitionDescription(
            Documentation =
                "Load closing prices/data for the specified date and closing dataset.  If particular indexes/volatilities have been identified in the scenario then only the closing data for those will be loaded.  Otherwise the full closing data set is loaded."
        )]
        public void WhenILoadCloseForDatasetFor(string dataSet, string dateStr)
        {
            dataSet = VariableManager.ExpandVariables(dataSet);
            dateStr = VariableManager.ExpandVariables(dateStr);
            if (!StringConversion.TryStringToDateTime(dateStr, out DateTime closeDate))
                StepLog.LogFatal($"{dateStr} is not a valid date");

            if (IndexContext.HasIndexes())
            {
                foreach (var index in IndexContext.GetMultipleIndexesFromContext())
                {
                    var response = MarketDataRepository.Value.LoadCloseForIndex(dataSet,closeDate.ToTTLDateTime(), index);
                    if (!response.Success)
                    {
                        if (MarketManagerContext.GetLoadCloseErrorCausesFail())
                            Response.LogResponse(response);
                        else
                        {
                            StepLog.LogToConsole($"Ignoring error for {index.Name}");
                            if (response.Messages != null)
                                foreach (var m in response.Messages)
                                    StepLog.LogToConsole($"\t{m?.Message}");
                        }
                    }
                }
            }

            if (VolatilityContext.HasVolatilities())
            {
                foreach (var vol in VolatilityContext.GetMultipleVolatilitiesFromContext())
                {
                    var response = MarketDataRepository.Value.LoadCloseForVolatility(dataSet, closeDate.ToTTLDateTime(),
                        vol);
                    if (!response.Success)
                    {
                        if (MarketManagerContext.GetLoadCloseErrorCausesFail())
                            Response.LogResponse(response);
                        else
                        {
                            StepLog.LogToConsole($"Ignoring error for {vol.Name}");
                            if (response.Messages != null)
                                foreach (var m in response.Messages)
                                    StepLog.LogToConsole($"\t{m?.Message}");
                        }
                    }
                }
            }

            if (!IndexContext.HasIndexes() && !VolatilityContext.HasVolatilities())
                Response.LogResponse(MarketDataRepository.Value.LoadClose(dataSet, closeDate.ToTTLDateTime(),
                    !MarketManagerContext.GetLoadCloseErrorCausesFail()));

        }

