                "Load universal prices. If particular indexes/volatilities have been identified in the scenario then only the universal data for those will be loaded.  Otherwise the full universal data set is loaded."
        )]
        public void WhenILoadUniversalPrices()
        {
            if (IndexContext.HasIndexes())
            {
                foreach (var index in IndexContext.GetMultipleIndexesFromContext())
                    Response.LogResponse(MarketDataRepository.Value.LoadUniversalForIndex(index));
            }

            if (VolatilityContext.HasVolatilities())
            {
                foreach (var vol in VolatilityContext.GetMultipleVolatilitiesFromContext())
                    Response.LogResponse(MarketDataRepository.Value.LoadUniversalForVolatility(vol));
