[When(@"I save close for dataset ""([^""]*)"" for ""([^""]*)""")]
        [StepDefinitionDescription(
            Documentation =
                "Saves closing prices/data for the specified date and closing dataset.  If particular indexes/volatilities have been identified in the scenario then only the closing data for those will be saved.  Otherwise the full closing data set is saved."
        )]
        public void WhenISaveCloseForDatasetFor(string dataSet, string dateStr)
        {
            dataSet = VariableManager.ExpandVariables(dataSet);
            dateStr = VariableManager.ExpandVariables(dateStr);
            if (!StringConversion.TryStringToDateTime(dateStr, out DateTime closeDate))
                StepLog.LogFatal($"{dateStr} is not a valid date");

            if (IndexContext.HasIndexes())
            {
                foreach (var index in IndexContext.GetMultipleIndexesFromContext())
                    Response.LogResponse(MarketDataRepository.Value.SaveCloseForIndex(dataSet, closeDate.ToTTLDateTime(),
                        index));
            }

            if (VolatilityContext.HasVolatilities())
            {
                foreach (var vol in VolatilityContext.GetMultipleVolatilitiesFromContext())
                    Response.LogResponse(MarketDataRepository.Value.SaveCloseForVolatility(dataSet, closeDate.ToTTLDateTime(),
                        vol));
            }

            if (!IndexContext.HasIndexes() && !VolatilityContext.HasVolatilities())
                Response.LogResponse(MarketDataRepository.Value.SaveClose(dataSet, closeDate.ToTTLDateTime()));

        }

