[RequiredColumn(Field = OpsServiceField)]
        [OptionalColumn(Field = CommonFieldDefinitions.Status)]
        [Given("the following operation service definitions exist")]
        [Given("the following op services exist")]
        [Then("the following operation service definitions exist")]
        [Then("the following op services exist")]
        [StepDefinitionDescription(Documentation =
            "Checks if a set of op services exist (optionally at a certain status - offline or online).")]
        public void ThenTheFollowingOpsServiceDefinitionsExist(Table table)
        {
            OpenlinkStepParameters.CheckTable(table);

            var ops = new List<string>();

            var activeOps = GetAllOperationServices(true);
            var allOps = GetAllOperationServices(activeOnly: false);

            foreach (var tableRow in table.Rows)
            {
                var opName = tableRow[OpsServiceField];

                ops.Add(opName);

                if (table.ContainsColumn(CommonFieldDefinitions.Status))
                {
                    var opStatus = tableRow[CommonFieldDefinitions.Status].ToLower();

                    if (!opStatus.Equals("offline", StringComparison.InvariantCultureIgnoreCase) &&
                        !opStatus.Equals("online", StringComparison.InvariantCultureIgnoreCase))
                    {
                        StepLog.LogError("Status must be either \'Online\' or \'Offline\'\n");
                    }
                    else if (activeOps.Contains(opName) &&
                             opStatus.Equals("offline", StringComparison.InvariantCultureIgnoreCase))
                    {
                        StepLog.LogError($"'{opName}' is at status 'Online'\n");
                    }
                    else if (!activeOps.Contains(opName) && allOps.Contains(opName) &&
                             opStatus.Equals("online", StringComparison.InvariantCultureIgnoreCase))
                    {
                        StepLog.LogError($"'{opName}' is at status 'Offline'\n");
                    }
                }

                if (!allOps.Contains(opName))
                    StepLog.LogError($"'{opName}' does not exist\n");
            }

            TriangleScenarioContext.Set(ops, OpsInContext);
        }

