[Given(@"the operation service definition ""(.*)"" exists in status ""(.*)""")]
        [Given(@"the op service ""(.*)"" exists in status ""(.*)""")]
        [Then(@"the operation service definition ""(.*)"" exists in status ""(.*)""")]
        [Then(@"the op service ""(.*)"" exists in status ""(.*)""")]
        [StepDefinitionDescription(Documentation = "Checks if an op service exists at a given status.")]
        public void GivenTheOperationServiceExistsInStatus(string opName, string opStatus)
        {
            opName = VariableManager.ExpandVariables(opName);
            opStatus = VariableManager.ExpandVariables(opStatus);
            opStatus = opStatus.ToLower();

            var activeOps = GetAllOperationServices(activeOnly: true);
            var allOps = GetAllOperationServices(activeOnly: false);

            if (!opStatus.Equals("online") && !opStatus.Equals("offline"))
            {
                StepLog.LogFatal("Status must be either 'Online' or 'Offline'");
            }
            else if (!allOps.Contains(opName))
            {
                StepLog.LogFatal($"'{opName}' does not exist");
            }
            else if (opStatus.Equals("online") && !activeOps.Contains(opName))
            {
                StepLog.LogFatal($"'{opName}' exists but at status 'Offline'");
            }
            else if (opStatus.Equals("offline") && activeOps.Contains(opName))
            {
                StepLog.LogFatal($"'{opName}' exists but at status 'Online'");
            }

            TriangleScenarioContext.Set(new List<string>() { opName }, OpsInContext);
        }

