[Given("the report builder parameters are as follows")]
        [RequiredColumnsWithChoice(GroupName = nameof(ColumnGroups.ReportDefParameterIdentifierFields))]
        [RequiredColumn(Field = ReportBuilderFieldDefinitions.ParameterValue)]
        [OptionalColumn(Field = ReportBuilderFieldDefinitions.DataSource)]
        [StepDefinitionDescription(Documentation = "Sets report parameter values on previously specified report.")]
        public void GivenTheReportBuilderParametersAreAsFollows(Table argtTable)
        {
            OpenlinkStepParameters.CheckTable(argtTable);
            VariableManager.ExpandTableVariables(argtTable);

            var rbHandle = ReportBuilderContext.GetReportBuilder();
            
            var reportParams = argtTable.Rows.Select(r => new TTLReportBuilderParam
            {
                ParameterName = argtTable.ContainsColumn(ReportBuilderFieldDefinitions.ParameterName) ? r[ReportBuilderFieldDefinitions.ParameterName] : null,
                ParameterTitle = argtTable.ContainsColumn(ReportBuilderFieldDefinitions.ParameterTitle) ? r[ReportBuilderFieldDefinitions.ParameterTitle] : null,
                ParameterValue = r[ReportBuilderFieldDefinitions.ParameterValue],
                ParameterDataSource = argtTable.ContainsColumn(ReportBuilderFieldDefinitions.DataSource) ? r[ReportBuilderFieldDefinitions.DataSource] : "ALL"
            }).ToList();

            reportParams = GetParamDetails(rbHandle.ReportDefinition, reportParams);

            if (!StepLog.HasErrors())
            {
                var dataSrc = ReportBuilderContext.GetDataSource();
                var rOutDir = ReportBuilderContext.GetReportOutputDir();
                var queryName = ReportBuilderContext.GetQueryName();
                
                // override report out directory if set
                if(!string.IsNullOrEmpty(rOutDir))
                    reportParams.Add(new TTLReportBuilderParam{ParameterName = ReportBuilderFieldDefinitions.ReportOutDir, ParameterValue = rOutDir});
                
                // override report query if set
                if(!string.IsNullOrEmpty(queryName))
                    reportParams.Add(new TTLReportBuilderParam{ParameterName = ReportBuilderFieldDefinitions.QueryName, ParameterValue = queryName});
                
                var response = _reportBuilderRepository.Value.SetReportBuilderParameters(rbHandle, reportParams);
                Response.LogResponse(response);
            }
        }

[When("I run the report builder")]
        [StepDefinitionDescription(Documentation =
            "Executes report definition. If output type is not specified using 'Given the report builder output type is ..' step, report results are stored in a context table that can then be exported using 'When I export the report builder output data ..' step.")]
        public void WhenIRunTheReportBuilder()
        {
            var rbHandle = ReportBuilderContext.GetReportBuilder();
            var rOutputType = ReportBuilderContext.GetOutputType();

            if (!string.IsNullOrEmpty(rOutputType))
            {
                var response = _reportBuilderRepository.Value.RunReportBuilderWithOutputType(rbHandle, rOutputType);
                Response.LogResponse(response);
            }
            else
            {
                var reportTbl = _reportBuilderRepository.Value.RunReportBuilder(rbHandle);
                ReportBuilderContext.AddReportOutputTable(reportTbl);
                Response.LogResponse(reportTbl);
            }
        }

