[When("I amend the saved query as follows")]
        [When("I modify the saved query as follows")]
        [When("I edit the query as follows")]
        [When("I edit the saved query as follows")]
        [OptionalColumn(Field = PageField)]
        [OptionalColumn(Field = ViewField)]
        [RequiredColumn(Field = FieldNameField)]
        [RequiredColumn(Field = ValueField)]
        [StepDefinitionDescription(
            Documentation =
                "Modifies a previously specified query.  If page is not specified, all references are assumed to be to page one of the query.  If the 'View' is not specified, Fields are assumed to relate to 'Transactions'.  Multiple values can be set by comma separating them.  You can add a value to an existing set of values by setting the field to '+= <extra value>'.  You can remove a value by setting the field to '-= <value to remove>'.  The same field can be appear more than once in the table.  So, for example, one row might add PWR-PHYS to the ins_type field and the next row might remove COMM-PHYS from the ins_type."
        )]
        public void WhenIAmendTheSavedQueryAsFollows(Table table)
        {
            VariableManager.ExpandTableVariables(table);
            // parameter checking fails because having columns caused Field and Value makes the 
            // checking code that this is a vertical table, so we do this poor man's checking
            foreach (var f in new[] { FieldNameField, ValueField })
                if (!table.ContainsColumn(f))
                    StepLog.LogError($"Column '{f}' required");

            if (!StepLog.HasErrors())
            {
                var query = SavedQueryContext.GetQuery();
                UpdateQueryFromTable(query, table);
            }
        }

