[When("I run the saved query")]
        [When("I run the query")]
        [When("I run the generic saved query")]
        [StepDefinitionDescription(Documentation = "Runs a previously specified query.")]
        public void WhenIRunTheQuery()
        {
            var query = SavedQueryContext.GetQuery();

            var queryResult = EndurDatabaseRepository.Value.ExecuteSavedQuery(query);
            Response.LogResponse(queryResult);
            SavedQueryContext.AddQueryResult(queryResult);
            SavedQueryContext.SetQueryType(query.QueryType);
            // run some extra SQL depending on the type of query that was run
            TTLOlfTableHandle results;
            string sql;

            if (query.QueryType == EnumTTLQueryType.Transaction)
            {
                sql =
                    $@"select ab.deal_tracking_num
                              from ab_tran ab 
                              inner join query_result qr on qr.query_result = ab.tran_num
                                where qr.unique_id = {queryResult.QueryResultId}";

                results = RunSql(sql);
            }
            else if (query.QueryType == EnumTTLQueryType.StldocDocument)
            {
                sql = $@"select distinct h.document_num                              
                             from stldoc_header h 
                              inner join {queryResult.QueryResultTable} qr on qr.query_result =  h.stldoc_hdr_hist_id
                                where qr.unique_id = {queryResult.QueryResultId}";

                results = RunSql(sql);
                var docNums = EndurTableRepository.Value.GetColumnValuesAsIntByColumnNum(results, 0);

                foreach (var docNum in docNums)
                {
                    var doc = _backOfficeRepository.Value.GetDocumentById(docNum);
                    DocumentContext.AddDocumentToContext(doc);
                }
            }
            else if (query.QueryType == EnumTTLQueryType.StldocEvent)
            {
                sql =
                    $"select query_result from {queryResult.QueryResultTable} where unique_id = {queryResult.QueryResultId}";

                results = RunSql(sql);
            }
            else if (query.QueryType == EnumTTLQueryType.AcsRuleBoDoc)
            {
                sql =
                    $"select query_result1 as query_result from query_result2_acs where unique_id = {queryResult.QueryResultId}";
                results = RunSql(sql);
            }
            else if (query.QueryType == EnumTTLQueryType.Index)
            {
                sql =
                    $"select query_result as query_result from query_result where unique_id = {queryResult.QueryResultId}";
                results = RunSql(sql);
                var indexIds = EndurTableRepository.Value.GetColumnValuesAsIntByColumnNum(results, 0);

                foreach (var indexId in indexIds)
                {
                    var idx = _marketDataRepository.Value.GetIndexById(indexId);
                    IndexContext.AddIndexToContext(idx);
                }
            }
            else
            {
                sql = $"select query_result from query_result where unique_id = {queryResult.QueryResultId}";
                results = RunSql(sql);
            }

            Response.LogResponse(results);
            if (!results.Response.Success)
                StepLog.LogFatal("Failed to get results for saved query");
            var rowCount = EndurTableRepository.Value.GetTableRowCount(results);
            StepLog.LogDebug(
                $"Retrieved {EndurTableRepository.Value.GetTableRowCount(results)} results");

            // add query_name column with the query name for export
            EndurTableRepository.Value.AddColumn(results, "query_name", EnumTTLColType.String);

            for (var i = 0; i < rowCount; i++)
                EndurTableRepository.Value.SetString(results, "query_name", i, query.QueryName);

            CommonSelectContext.AddResults(EndurTableConverter.Value.OlfTableToDataTable(results));
        }

