        {
            var serviceName = ServiceManagerContext.GetServiceName();
            var response = ServiceManagerRepository.Value.StopServiceGroup(serviceName,
                StepRepeatContext.GetMaxWaitTime(), StepRepeatContext.GetMaxRepeats(),
                StepRepeatContext.GetRetryInterval());
            Response.LogResponse(response);
            SleepHelper.Sleep(5000);
            response = ServiceManagerRepository.Value.StartServiceGroup(serviceName,
                StepRepeatContext.GetMaxWaitTime(), StepRepeatContext.GetMaxRepeats(),
                StepRepeatContext.GetRetryInterval());
            Response.LogResponse(response);
        }

