        [RequiredColumn(Field = TransactionFieldDefinitions.UDSRId)]
        [RequiredColumn(Field = TransactionFieldDefinitions.UDSRName)]
        [RequiredColumn(Field = TransactionFieldDefinitions.UDSRClassification)]
        [OptionalColumn(Field = TransactionFieldDefinitions.UDSRType)]
        [StepDefinitionDescription(Documentation =
            "Used to tell Triangle the Id/Name/Class of user defined simulation results.  Class is typically Transaction or Leg.  It is not necessary to define General UDSRs.  The type of the result is assumed to be double unless specified")]
        public void WhenIStoreTheSimulationResults(Table userDefinedResults)
        {
            OpenlinkStepParameters.CheckTable(userDefinedResults);
            VariableManager.ExpandTableVariables(userDefinedResults);
            foreach (var row in userDefinedResults.Rows)
            {
                var resultType = typeof(double);
                if (row.HasValue(TransactionFieldDefinitions.UDSRType))
                {
                    if (!StringConversion.TryStringToType(row[TransactionFieldDefinitions.UDSRType], out resultType))
                        StepLog.LogError($"Unrecognized type {row[TransactionFieldDefinitions.UDSRType]}");
                }

                if (StringConversion.TryStringToInt(row[TransactionFieldDefinitions.UDSRId], out var id))
                    SimulationContext.AddUserDefinedSimulationResult(id, row[TransactionFieldDefinitions.UDSRName],
                        row[TransactionFieldDefinitions.UDSRClassification], resultType);
                else StepLog.LogError($"Invalid ID {row[TransactionFieldDefinitions.UDSRId]}");
            }
        }

[Given("sim results exist as follows")]
        [Given("simulation results exist as follows")]
        [Then("sim results exist as follows")]
        [Then("simulation results exist as follows")]
        [RequiredColumn(Field = TransactionFieldDefinitions.SimRunDate)]
        [RequiredColumn(Field = TransactionFieldDefinitions.SimReference)]
        [OptionalColumn(Field = TransactionFieldDefinitions.Portfolio)]
        [RequiredColumn(Field = TransactionFieldDefinitions.SimRevalType)]
        [StepDefinitionDescription(Documentation = "Asserts that simulation results exist for the specified date, reference, reval type and, optionally, portfolio(s).  Where a portfolio is specified a single portfolio name maybe be given, or a * to indicate all portfolios, or a regular expression to indicate selected portfolios only.")]
        public void GivenSimResultsExistAsFollows(Table exportSpecification)
        {
            VariableManager.ExpandTableVariables(exportSpecification);
            OpenlinkStepParameters.CheckTable(exportSpecification);

            foreach (var row in exportSpecification.Rows)
            {
                var runDate = row.GetDate(TransactionFieldDefinitions.SimRunDate);
                var reference = row.GetString(TransactionFieldDefinitions.SimReference);
                var portfolio = row.GetOrDefault(TransactionFieldDefinitions.Portfolio, "*");
                var revalType = row.GetString(TransactionFieldDefinitions.SimRevalType);

                var simRuns = GetSimulationRuns(runDate, reference, portfolio, revalType);
                if (!simRuns.Any())
                    StepLog.LogDebug($"Warning: no sim results for {runDate}, {reference}, {portfolio}, {revalType}");

                SimulationContext.AddSimulationRuns(simRuns);
            }
        }

