[When(@"I export the sim results for scenario name ""(.*)"" with test key ""(.*)"" as follows")]
        [When(@"I export the simulation results for scenario name ""(.*)"" with test key ""(.*)"" as follows")]
        [StepDefinitionDescription(
            Documentation =
                "Exports the specified sim results to the comparison database.  Must be preceded by 'Given sim results exist'."
        )]
        [RequiredColumn(Field = TransactionFieldDefinitions.SimResult)]
        [OptionalColumn(Field = TransactionFieldDefinitions.SimTable)]
        public void WhenIExportTheSimResultsForScenarioNameAsFollows(string scenarioName, string testKey,
            Table exportSpecification)
        {
            OpenlinkStepParameters.CheckTable(exportSpecification);
            scenarioName = VariableManager.ExpandVariables(scenarioName);
            testKey = VariableManager.ExpandVariables(testKey);
            if (SimulationContext.HasSimulationResults())
            {
                var results = SimulationContext.GetSimulationResults();
                ExportAllSimResultsTask(exportSpecification, results, testKey, scenarioName, EndurComparisonContext.GetIncludeTestLabel(), SimulationContext.HasExportDirectory() ? SimulationContext.GetExportDirectory() : null);
            }
            else if (SimulationContext.HasSimResultRuns())
            {
                ExportByRunIds(scenarioName, testKey, exportSpecification, SimulationContext.GetSimResultRuns());
            }
            else
            {
                if (SimulationContext.GetEmptyExportIsError())
                    StepLog.LogError("No simulation results to export");
            }
        }

