[When(@"I insert TOF ticket data as follows")]
        [StepDefinitionDescription(Documentation = "Insert entries into tof_ticket_data and one row into tof_ticket_header.  The TOF System and Server references can be specified by 'Given a TOF Server/System Reference of XX' or via App.Config")]
        [RequiredColumn(Field = FidField)]
        [RequiredColumn(Field = ValueField)]
        public void WhenIInsertATOFTicketDataAsFollows(Table ticketData)
        {
            VariableManager.ExpandTableVariables(ticketData);
            OpenlinkStepParameters.CheckTable(ticketData);
            var systems = GetTOFSystems();
            var systemRef =
                TriangleScenarioContext.GetFromScenarioContextOrConfig<string>(SystemRefField, "TOF.SystemRef",
                    "TOF System Reference");
            var serverRef =
                TriangleScenarioContext.GetFromScenarioContextOrConfig<string>(ServerRefField, "TOF.ServerRef",
                    "TOF Server Reference");
            var dealDate = DateTime.Now.Date;

            if (!systems.ContainsKey(systemRef))
                StepLog.LogError($"Invalid system reference.  Possible values {string.Join(",", systems.Keys)}");

            var fids = ticketData.Rows.Select(r => r[FidField]).ToList();
            foreach (var f in fids)
                if (fids.Count(a => a == f) > 1)
                    StepLog.LogError($"Duplicate FID {f}");

            if (!StepLog.HasErrors())
            {
                var systemRefId = systems[systemRef];
                var ticketNumber = GetNextTicketNumber(systemRefId, serverRef);
                var ticketRef = $"{DateTime.Now:yyyyMMdd}{ticketNumber}";

                BeginTran();

                try
                {
                    foreach (var row in ticketData.Rows)
                        if (StringConversion.TryStringToInt(row[FidField], out var fid))
                            InsertTofTicketData(systemRefId, serverRef, ticketRef, fid, row[ValueField]);
                        else StepLog.LogError($"Invalid FID {row[FidField]}");

                    if (!StepLog.HasErrors())
                    {
                        InsertTofTicketHeader(systemRefId, serverRef, dealDate, ticketNumber, ticketRef);
                        StepLog.LogToConsole(
                            $"System Ref: {systemRef} and Server Ref: {serverRef} -> Ticket Number {ticketNumber}");
                    }
                }
                catch (Exception e)
                {
                    StepLog.LogError($"Unhandled exception : {e.Message}");
                }


                if (StepLog.HasErrors())
                    RollbackTran();
                else CommitTran();
            }
        }

