[Given(@"a TPM workflow for ""(.*)"" exists with variables as follows")]
        [RequiredColumn(Field = CommonFieldDefinitions.Value)]
        [RequiredColumn(Field = CommonFieldDefinitions.Variable)]
        public void GivenATPMWorkflowForExistsWithVariablesAsFollows(string definitionName, Table variables)
        {
            definitionName = VariableManager.ExpandVariables(definitionName);
            VariableManager.ExpandTableVariables(variables);
            OpenlinkStepParameters.CheckTable(variables);
            ValidateTpmDefinition(definitionName, false);

            var variableNames =
                EndurDatabaseRepository.Value.RunSqlToStrings("select  type_name from tpm_var_info_types");

            var variableJoins = new StringBuilder();
            var n = 0;
            foreach (var row in variables.Rows)
            {
                var name = row[CommonFieldDefinitions.Variable].Trim();
                var value = row[CommonFieldDefinitions.Value].Trim();
                if (!variableNames.Contains(name))
                {
                    StepLog.LogError($"{name} is not a valid TPM info field");
                }
                else
                {
                    variableJoins.AppendLine(
                        $"inner join tpm_var_info i{n} on i{n}.instance_id = br.instance_id and i{n}.tpm_var_value = '{value}'");
                    variableJoins.AppendLine(
                        $"inner join tpm_var_info_types t{n} on  t{n}.type_id = i{n}.tpm_var_id and t{n}.type_name = '{name}'");
                    n++;
                }
            }


            if (!StepLog.HasErrors())
            {
                var sql = $@"select br.instance_id
                            from bpm_running br
                            inner join bpm_status bs on br.bpm_status = bs.id_number
                            inner join bpm_definition bd on br.bpm_definition_id = bd.id_number
                            {variableJoins}
                            where bd.bpm_name = '{definitionName}'";

                var ids = SqlRunner.RunSqlToInts(sql);

                if (!ids.Any())
                    StepLog.LogFatal($"No running workflows found for {definitionName} with specified variable values");

                foreach (var id in ids)
                    TpmContext.AddTask(new TpmTask { ProcessId = id });
            }
        }

[Given("I wait for the following TPM tasks to be assigned to me")]
        [Given("I wait until the following TPM tasks are assigned to me")]
