        [StepDefinitionDescription(Documentation =
            "Behaves the sames as 'Given the following TPM tasks are assigned to me' except if the tasks are not assigned it will wait and retry until they are, or until a configurable number of retries or maximum time has elapsed.  See the steps under 'Step Repeat (Common)' for an explanation on how to control the frequency and maximum number of retries.")]
        public void GivenIWaitForFollowingTPMTasksToBeAssignedToMe(Table expectedTasks)
        {
            // Don't check the column names as the TPM results can contain an arbitrary set of variables
            // in addition to the standard set of TPM task attributes
            VariableManager.ExpandTableVariables(expectedTasks);
            var succeeded = RepeaterFactory.Repeater.RepeatUntil(() =>
            {
                var actualTasks = _tpmRepository.Value.GetAssignedTpmTasks();
                var ok = MatchTasks(expectedTasks, actualTasks, true);
                if (StepLog.HasErrors())
                    StepLog.LogFatal("Abandoning wait");
                return ok;
            }, "Abandoned wait for tasks to be assigned to me");

            if (!succeeded)
            {
                StepLog.LogError("Abandoned wait for tasks to be assigned to me");
                var assignableTasks = _tpmRepository.Value.GetAssignedTpmTasks();
                ShowNonMatchingTasks(assignableTasks, "The following tasks were assigned to me");
            }
        }

