[Given(@"the TPM table variable ""(.*)"" is as follows")]
        public void GivenTheTPMTableVariableIsAsFollows(string tableVariableName, Table expectedVariables)
        {
            VariableManager.ExpandTableVariables(expectedVariables);
            // we cannot check the table because the columns can vary for each installation/workflow

            var tasks = TpmContext.GetAtLeastOneTask("No previously specified tasks");

            foreach (var t in tasks)
            {
                var actualValues = _tpmRepository.Value.GetTableVariables(t.ProcessId, tableVariableName);
                if (!actualValues.Response.Success)
                {
                    Response.LogResponse(actualValues.Response);
                    StepLog.LogFatal("Failed to get variables");
                }

                EndurTableComparer.Value.AssertTableContains(expectedVariables, actualValues);
            }
        }

[Given("the TPM variables are as follows")]
        [Given("the TPM task variables are as follows")]
        [Given("the TPM variables contain the following")]
        [Then("the TPM variables contain the following")]
        [Given("the TPM workflow variables contain the following")]
        [Then("the TPM workflow variables contain the following")]
        [RequiredColumn(Field = CommonFieldDefinitions.Value)]
        [RequiredColumn(Field = CommonFieldDefinitions.Variable)]
        public void GivenTheTPMVariablesAreAsFollows(Table expectedVariables)
        {
            VariableManager.ExpandTableVariables(expectedVariables);
            OpenlinkStepParameters.CheckTable(expectedVariables);

            var instanceId = GetCurrentInstanceId();

            var taskVariables = _tpmRepository.Value.GetVariables(instanceId);
            Response.LogResponse(taskVariables);
            if (!taskVariables.Response.Success)
                StepLog.LogFatal("Failed to get variables");

            var variableNames = EndurTableRepository.Value.GetColumnValuesAsStringByColumnNum(taskVariables, 0);
            var variableValues = EndurTableRepository.Value.GetColumnValuesAsStringByColumnNum(taskVariables, 1);

            foreach (var row in expectedVariables.Rows)
            {
                var name = row[CommonFieldDefinitions.Variable].Trim();
                var expectedValue = row[CommonFieldDefinitions.Value].Trim();
                if (variableNames.Contains(name))
                {
                    var actualValue = variableValues[variableNames.IndexOf(name)];
                    if (expectedValue != actualValue)
                        StepLog.LogError($"{name}: Expected {expectedValue}, Actual {actualValue}");
                }
                else
                {
                    StepLog.LogError($"A variable called '{name}' does not exist");
                }
            }

            EndurTableRepository.Value.Dispose(taskVariables);
        }

