[Then(@"the attempt to complete the TPM task fails with the message ""(.*)""")]
        public void ThenTheAttemptToCompleteTheTPMTaskFailsWithTheMessage(string errorMessage)
        {
            errorMessage = VariableManager.ExpandVariables(errorMessage);
            StepDependencies.ClearDependency(TpmDependency);
            if (!TryErrorContext.HasErrors())
            {
                StepLog.LogError("TPM task completed without any errors");
            }
            else
            {
                var actualErrorMessage = TryErrorContext.GetErrorMessage();
                if (actualErrorMessage.Contains(errorMessage))
                {
                    TryErrorContext.RemoveAllErrors();
                }
                else
                {
                    StepLog.LogError("Task failed, but with different error message");
                    StepLog.LogError(actualErrorMessage);
                }
            }
        }

[Then("the attempt to complete the TPM task succeeds")]
        public void ThenTheAttemptToCompleteTheTPMTaskSucceeds()
        {
            StepDependencies.ClearDependency(TpmDependency);
            if (TryErrorContext.HasErrors())
            {
                StepLog.LogError("TPM task failed");
                StepLog.LogError(TryErrorContext.GetErrorMessage());
            }
        }

[Then(@"the TPM workflow status is ""(.*)""")]
        public void ThenTheTPMWorkflowStatusIs(string expected)
        {
            expected = VariableManager.ExpandVariables(expected);
            var instanceId = GetCurrentInstanceId();
            var status = EndurDatabaseRepository.Value.RunSqlToStrings(
                $@"select s.status 
                    from bpm_history h
                    inner join tpm_running_status_table s on h.bpm_status = s.id_number
                    where instance_id = {instanceId}");
            if (!status.Any()) StepLog.LogFatal($"No entry in bpm_history for {instanceId}");
            var actual = status.First();
            if (!string.Equals(expected, actual, StringComparison.InvariantCultureIgnoreCase))
                StepLog.LogFatal($"Expected '{expected}'.  Actual '{actual}'");
        }

