[Given(@"TPM table parameter ""([^""]*)"" as follows")]
        [StepDefinitionDescription(Documentation =
            "Defines a parameter of type ArgTable that will be passed when triggering a TPM definition.  Column types should be specified by using column names of the form <name>:<type>.  e.g. price:double")]
        public void GivenTPMTableParametersAsFollows(string parameterName, Table table)
        {
            VariableManager.ExpandVariables(parameterName);
            VariableManager.ExpandTableVariables(table);
            var t = EndurTableConverter.Value.SpecflowToOlfTable(table);
            var parameters = new TTLOlfTable(EndurTableRepository.Value, GetTpmParameters());
            GetTpmParameters();
            if (!parameters.ColumnNames.Contains(parameterName))
                parameters.AddColumn(parameterName, EnumTTLColType.String);
            var newRow = parameters.AddRow();
