[When("I wait for the TPM workflow to complete")]
        [StepDefinitionDescription(Documentation =
            "Waits for a previously specified TPM workflow to complete (successfully, or otherwise).  See the steps under 'Step Repeat (Common)' for an explanation on how to control the frequency and maximum number of times Triangle will check.")]
        public void WhenIWaitTheTPMWorkflowToComplete()
        {
            var instanceId = GetCurrentInstanceId();
            RepeaterFactory.Repeater.RepeatUntil(() =>
            {
                // 1 - Initialising
                // 2 - Running
                // 3 - Start failed
                // 4 - succeeded
                // 5 - Failed
                // 6 - succeeded with errors
                // 7 - cancelled
                // 8 - Suspended
                var count = EndurDatabaseRepository.Value.RunSqlToRowCount(
                    $"select 1 from bpm_history where instance_id = {instanceId} and bpm_status in (3,4,5,6,7,8)");
                return count > 0;
            }, "Timed out waiting for TPM workflow to complete");
        }

