[When("I book-out deals as follows")]
        [StepDefinitionDescription(Documentation =
            "Book-outs for pairs of deals.  Each pair consists of two deal numbers and the side.  If the side is not specified it defaults to 1.  If the transfer date is not specified it defaults to today. Deals can be identified by labels or deal numbers.")]
        [RequiredColumnsWithChoice(GroupName = nameof(ColumnGroups.DealA))]
        [RequiredColumnsWithChoice(GroupName = nameof(ColumnGroups.DealB))]
        [OptionalColumn(Field = CertificateFields.SideAField)]
        [OptionalColumn(Field = CertificateFields.SideBField)]
        [RequiredColumn(Field = CertificateFields.QuantityField)]
        [OptionalColumn(Field = CertificateFields.TransferDateField)]
        public void WhenIBookOutDealsAsFollows(Table table)
        {
            VariableManager.ExpandTableVariables(table);
            OpenlinkStepParameters.CheckTable(table);
            foreach (var row in table.Rows)
            {
                
                var dealNumA = GetDealNum(row, CertificateFields.DealNumberAField, CertificateFields.TestLabelAField);
                var dealNumB = GetDealNum(row, CertificateFields.DealNumberBField, CertificateFields.TestLabelBField);
                Response.LogResponse(
                    _recsRepository.Value.BookOutDeals(dealNumA, row.GetOrDefault(CertificateFields.SideAField, 1), dealNumB,
                        row.GetOrDefault(CertificateFields.SideBField, 1),
                        row.GetDouble(CertificateFields.QuantityField),
                        row.GetOrDefault(CertificateFields.TransferDateField, DateTime.Today).ToTTLDateTime()));
            }
        }

