        [When("I add delivery and receipt nominations to the non-transit cargo")]
        public void WhenIAddDeliveryAndReceiptParcelsToTheNon_TransitCargo()
        {
            var cargo = SchedulingContext.GetSingleCargo();

            var delParcelHandles = SchedulingContext.GetParcels(EnumTTLDeliveryReceipt.Delivery);
            var recParcelHandles = SchedulingContext.GetParcels(EnumTTLDeliveryReceipt.Receipt);

            var delDealDataList = GetDealData(delParcelHandles, EnumTTLDeliveryReceipt.Delivery);
            var recDealDataList = GetDealData(recParcelHandles, EnumTTLDeliveryReceipt.Receipt);


            var nomination = _schedulingRepository.Value.AddNominationToNonTransitCargo(cargo, recDealDataList[0], delDealDataList[0]);
            Response.LogResponse(nomination.Response);

        }

