[RequiredColumn(Field = TransitTemplate)]
        [RequiredColumn(Field = CommonOpenlinkFields.TransactionStatus)]
        [OptionalColumn(Field = CommonOpenlinkFields.TestLabel)]
        [OptionalColumnGroup(GroupName = nameof(ColumnGroups.CargoAttributes))]
        [When("I prepare a transit cargo as follows")]
        public void WhenIPrepareATransitCargoAsFollows(Table cargoProperties)
        {
            OpenlinkStepParameters.CheckTable(cargoProperties, 1);
            VariableManager.ExpandTableVariables(cargoProperties);
            var row = cargoProperties.Rows[0];
            var templateNum = GetTemplateDealNum(row[TransitTemplate]);

            var cargo = _schedulingRepository.Value.CreateTransitCargo(templateNum);
            Response.LogResponse(cargo);
            if (cargo.Response.Success)
            {
                if (row.HasValue(CommonOpenlinkFields.TestLabel))
                    cargo.TestLabel = row[CommonOpenlinkFields.TestLabel];
                SchedulingContext.AddCargo(cargo);
                _cargoFieldManager.AssertOrAssignFromTableRow(cargo, row, cargoProperties.GetColumnHeadings().ToList(),
                    AssertAssignCheck.Assign);
            }
        }

