            CreateNominationForCargo();

            var columnHeadings = nomTable.GetColumnHeadings().ToList();
            var nominations = SchedulingContext.GetMultipleNominations();

            if (!nominations.Any())
                StepLog.LogFatal("No nominations previously identified");

            if (nominations.Count == 1)
            {
                if (nomTable.RowCount != 1)
                    StepLog.LogFatal($"Row mismatch. Expected 1 row for '{nominations.First().TestLabel}'");

                _nominationFieldManager.AssertOrAssignFromTableRow(nominations.First(), nomTable.Rows[0], columnHeadings, AssertAssignCheck.Assign);
            }
            else
            {
                for (var rowNum = 0; rowNum < nomTable.RowCount; rowNum++)
                {
                    var row = nomTable.Rows[rowNum];
                    var t = _nominationFieldManager.FindMatching(nominations, row, columnHeadings);

                    if (!t.Any())
                        StepLog.LogError($"No matching nominations for row {rowNum} : {row.GetPrimaryKeyExpression()}");
                    else if (t.Count > 1)
                        StepLog.LogError($"Multiple matching nominations for row {rowNum} : {row.GetPrimaryKeyExpression()}");

                    _nominationFieldManager.AssertOrAssignFromTableRow(t.First(), row, columnHeadings, AssertAssignCheck.Assign);
                }
            }

        }

