        [StepDefinitionDescription(Documentation = "Adds one of more delivery tickets to a nomination.  The nomination must have been identified by a previous step in the same scenario")]
        [OptionalColumnGroup(GroupName = nameof(ColumnGroups.DeliveryTicketAttributes))]

        public void WhenIAddDeliveryTicketsAsFollows(Table table)
        {
            VariableManager.ExpandTableVariables(table);
            OpenlinkStepParameters.CheckTable(table);
            var cargo = SchedulingContext.GetSingleCargo();
            var nominationHandle = SchedulingContext.GetSingleNomination();
            var nom = new TTLNomination(_schedulingRepository.Value, nominationHandle);
            EnumTTLDeliveryReceipt direction =
                nom.GetField(EnumTTLNominationField.NominationDeliveryDealExternalLentity).DisplayString ==
                "" ? EnumTTLDeliveryReceipt.Receipt : EnumTTLDeliveryReceipt.Delivery;
            var columnHeadings = table.GetColumnHeadings();
            foreach (var row in table.Rows)
            {
                var deliveryTicket =
                    _schedulingRepository.Value.AddDeliveryTicketToNomination(cargo, nominationHandle, direction);
                Response.LogResponse(deliveryTicket);
                if (deliveryTicket.Response.Success)
                {

                    _deliveryTicketFieldManager.AssertOrAssignFromTableRow(deliveryTicket, row, columnHeadings,
                        AssertAssignCheck.Assign);
                }
            }
        }

