[OptionalColumnGroup(GroupName = nameof(ColumnGroups.CashflowAttributes))]
        [When(@"I remove cashflows for leg ""(.*)"" as follows")]
        [When(@"I delete cashflows for leg ""(.*)"" as follows")]
        [StepDefinitionDescription(
            Documentation =
                "Deletes/Removes one or more cashflows based on the supplied table. Must be followed by 'And I process the transaction to ..'")]
        public void WhenIRemoveCashflowsForLegAsFollows(string leg, Table table)
        {
            OpenlinkStepParameters.CheckTable(table);
            VariableManager.ExpandTableVariables(table);
            var legNum = GetLegNum(leg);
            var t = TransactionContext.GetSingleTransactionFromContext();
            var tran = new TTLTransaction(TradeRepository.Value, t);

            // Work out the IDs of the cashflows that we plan to remove
            var mappings = GetCashflowIdsForRows(tran, legNum, table, false);

            // It's possible that there is some overlap, so construct a unique set of ids
            var cashflowIdsToRemove = new HashSet<int>();
            for (var rowNum = 0; rowNum < table.RowCount; rowNum++)
            {
                if (!mappings[rowNum].Any())
                    StepLog.LogToConsole($"Warning: row {rowNum} does not match any existing cashflows");
                foreach (var m in mappings[rowNum])
                    cashflowIdsToRemove.Add(m);
            }

            StepLog.LogToConsole($"Remove {string.Join(",", cashflowIdsToRemove)}");
            Response.LogResponse(TradeRepository.Value.RemoveCashflows(t, legNum, cashflowIdsToRemove.ToList()));
        }

