[Given(@"a ""(.*)"" instrument with ticker ""(.*)"" exists")]
        [Then(@"a ""(.*)"" instrument with ticker ""(.*)"" exists")]
        [Given(@"a ""(.*)"" holding instrument with ticker ""(.*)"" exists")]
        [Then(@"a ""(.*)"" holding instrument with ticker ""(.*)"" exists")]
        [StepDefinitionDescription(
            Documentation =
                "Asserts that a single instrument of a specific type (case-sensitive), with a given ticker exists")
        ]
        public void GivenAInstrumentWithTickerExists(string insType, string ticker)
        {
            insType = VariableManager.ExpandVariables(insType);
            ticker = VariableManager.ExpandVariables(ticker);

            var handle = TradeRepository.Value.GetInstrumentByTicker(ticker, insType);
            if (handle.None) StepLog.LogFatal($"Failed to find {insType} instrument '{ticker}' ");

            if (string.IsNullOrEmpty(handle.TestLabel))
                handle.TestLabel = ticker;

            if (string.IsNullOrEmpty(handle.Reference))
                handle.Reference = ticker;
            TransactionContext.RemoveTransactionFromContext(ticker);

            TransactionContext.AddTransactionToContext(handle);
        }

