[When(@"I retrieve transactions with test label like ""(.*)""")]
        [When(@"I retrieve transactions matching test label ""(.*)""")]
        [When("I retrieve transactions with test label like '(.*)'")]
        [StepDefinitionDescription(
            Documentation = "Use * or % to indicate wild-carding of the test label")]
        public void WhenIRetrieveTransactionsWithTestLabelLike(string testLabel)
        {
            testLabel = TestLabel.Expand(testLabel);
            var pattern = testLabel.Replace('*', '%');

            var sql =
                $"select deal_num, test_label from {SpecflowRefMapFields.TransactionRefMapTable} where test_label like '{pattern}' and exists (select 1 from ab_tran ab where ab.deal_tracking_num = deal_num and ab.current_flag = 1)";
            RetrieveTransactionsUsingSql(sql);
        }

