[When(@"I retrieve transactions with test label like ""(.*)"" in status (.*)")]
        [When(@"I retrieve transactions matching test label ""(.*)"" in status (.*)")]
        [When("I retrieve transactions with test label like '(.*)' in status (.*)")]
        [StepDefinitionDescription(
            Documentation =
                "Retrieves transactions with test labels that match the specified pattern and are in the specified status. Useful if you wish to retrieve transactions that are part of a two-step amendment process (e.g. Amended New or Buyout New) that are not the 'current' version of the transaction. Use * or % to indicate wild-carding of the test label.")]
        public void WhenIRetrieveTransactionsWithTestLabelLikeAtStatus(string testLabel, string status)
        {
            testLabel = TestLabel.Expand(testLabel);
            status = TestLabel.Expand(status);
            var pattern = testLabel.Replace('*', '%');
            var sql =
                $@"select tran_at_status.tran_num, m.test_label
                   from ab_tran ab
                        inner join user_specflow_tran_ref_map m on m.deal_num = ab.deal_tracking_num and ab.current_flag = 1
                        inner join ab_tran tran_at_status on ab.deal_tracking_num = tran_at_status.deal_tracking_num
                        inner join trans_status ts on tran_at_status.tran_status = ts.trans_status_id
                        where ts.name = '{status}'
                        and m.test_label like '{pattern}' ";
            RetrieveTransactionsUsingSql(sql, true);
        }

