[When(@"I label the buyout ""(.*)""")]
        [StepDefinitionDescription(
            Documentation =
                "Applies the test label to the trade generated by a partial buyout.  Must be preceded by 'When I buyout the transaction ...'")]
        public void WhenILabelTheBuyout(string testLabel)
        {
            testLabel = VariableManager.ExpandVariables(testLabel);
            var t = TransactionContext.GetSingleTransactionFromContext();
            var sql = $@"select ab.deal_tracking_num, '{testLabel}'
                                from ab_tran ab                                                                        
                                where ab.current_flag = 1 and                                                          
                                ab.deal_tracking_num in (                                                              
                                     select MAX(ba_deal.deal_tracking_num)                                              
                                     from ab_tran p
                                     inner join buyout_aux ba on ba.deal_num = p.deal_tracking_num                               
                                     inner join ab_tran ba_deal on ba_deal.tran_num = ba.split_tran_num                    
                                     where p.deal_tracking_num = {t.DealNum} and p.current_flag = 1 and ba.buyout_status = 0
                                       and ba_deal.deal_tracking_num > p.tran_num -- don't pick up any buyouts from earlier versions of the deal

                                )                                                   
                                ";

            StepLog.LogToConsole(sql);
            LabelTransactionsBySql(sql, 1);
        }

