[RequiredColumn(Field = CommonOpenlinkFields.TestLabel)]
        [OptionalColumn(Field = CommonFieldDefinitions.TestCategory)]
        [OptionalColumn(Field = TransactionFieldDefinitions.TranReference)]

        #endregion

        [When("I label the transactions as follows")]
        [When("I label the transaction as follows")]
        [StepDefinitionDescription(
            Documentation =
                "Labels existing transactions with a Test Label, and optionally a Test Category.  If more than one transaction exists and more than one test label is supplied then transaction reference is required to identify which label should be applied to which transaction")]
        public void WhenILabelTheTransactionsAsFollows(Table table)
        {
            VariableManager.ExpandTableVariables(table);
            var isReferenceSupplied = table.ContainsColumn(TransactionFieldDefinitions.TranReference);
            if (!isReferenceSupplied && table.RowCount > 2)
                StepLog.LogFatal("Trade reference required if labelling multiple trades");

            var transactions = TransactionContext.GetMultipleTransactionsFromContext();

            if (transactions.Count > 1 && !isReferenceSupplied)
                StepLog.LogFatal(
                    $"{transactions.Count} transactions previously specified, but only one label supplied.  Reference is required to uniquely identify which transaction should be labelled");

            foreach (var row in table.Rows)
            {
                TTLTransactionHandle tran;
                if (isReferenceSupplied)
                {
                    var tranReference = row[TransactionFieldDefinitions.TranReference];
                    tran =
                        transactions.FirstOrDefault(
                            t =>
                                t.Reference
                                    .Equals(tranReference));


                    if (tran == null)
                        StepLog.LogError(
                            $"No previously specified transaction with reference '{tranReference}'");
                }
                else
                {
                    tran = transactions.FirstOrError(
                        "More than one transaction previously specified.  Use transaction reference to identify to which one the test label should be applied");
                }

                if (tran != null)
                {
                    tran.TestLabel = TestLabel.Expand(row[CommonOpenlinkFields.TestLabel]);
                    if (row.TryGetValue(CommonFieldDefinitions.TestCategory, out var tc))
                        tran.TestCategory = tc;
                }
            }

            PersistTestReferenceData(transactions);
        }

