[When(@"I lock the transaction for user ""(.*)""")]
        [StepDefinitionDescription(
            Documentation =
                @"Locks the previously identified transaction. Note: This step uses a direct database connection.")
        ]
        public void WhenILockTheTransactionForUser(string username)
        {
            username = VariableManager.ExpandVariables(username);
            var userId = GetUserId(username);
            var tranNum = TransactionContext.GetSingleTransactionFromContext().TranNum;

            #region sql

            var query = $@"begin tran
            DECLARE @return_value int,
            @last_update datetime

            EXEC    @return_value = [dbo].[set_deal_lock]

            @tran_num = {tranNum},
            @lock_type = 2,
            @lock_user_id = {userId},
            @lock_by_user_id = {Session.Value.GetUserId()},
            @last_update = @last_update OUTPUT,
            @global_session_id = 0,
            @executing_module_id = 0
            commit";

            #endregion

            ExecuteNonQuery(query);
        }

