[StepDefinitionDescription(
            Documentation =
                "Sets the settlement instructions for the specified currency/delivery type.  Must be preceded by a step to identify the collateral.  Note that the settlement instructions are not saved until 'I save the settlement instructions'.  If adding multiple items of collateral you may use ISIN to indicate which settlement instructions relate to which collateral")
        ]
        [When("I set collateral settlement instructions as follows")]
        [OptionalColumn(Field = CommonOpenlinkFields.TestLabel)]
        [RequiredColumn(Field = SettlementInstructionFields.InternalOrExternal)]
        [OptionalColumn(Field = RepoCollateralFields.RepoCollateralIsin)]
        [OptionalColumn(Field = SettlementInstructionFields.Currency)]
        [RequiredColumn(Field = SettlementInstructionFields.Delivery)]
        [RequiredColumn(Field = SettlementInstructionFields.BusinessUnit)]
        [OptionalColumn(Field = SettlementInstructionFields.FXSwapNearFar)]
        [OptionalColumn(Field = SettlementInstructionFields.SettleName)]
        [OptionalColumn(Field = SettlementInstructionFields.SettleId)]
        public void WhenISetCollateralSettlementInstructionsAsFollows(Table table)
        {
            OpenlinkStepParameters.CheckTable(table);
            VariableManager.ExpandTableVariables(table);
            foreach (var tran in TransactionContext.GetCollateralFromContext())
                foreach (var row in table.Rows)
                {
                    if (row.TryGetValue(RepoCollateralFields.RepoCollateralIsin, out var value))
                    {
                        // Get the ISIN for this transaction and if it doesn't match then this settlement instruction
                        // is not intended for this item of collateral
                        var isin = TradeRepository.Value.GetFieldDisplayString(tran, EnumTTLTransactionSubObjectType.Transaction, 150, 0, 0, -1, -1, -1);
                        if (!string.Equals(isin, value))
                            continue;
                    }

                    SetSettlementInstructions(row, tran);
                }
        }

