[When(@"I add an underlying instrument on side ""([^""]*)"" of type ""(.*)"" and ticker ""(.*)""")]
        [StepDefinitionDescription(
            Documentation =
                "Sets the underlying Instrument for the previously identified Transaction or Instrument given an instrument type (e.g. GBND) and ticker."
        )]
        public void WhenIAddAnUnderlyingInstrumentOnSideOfTypeAndTicker(string side, string instrumentType, string ticker)
        {
            var tranHandle = TransactionContext.GetSingleTransactionFromContext();
            instrumentType = VariableManager.ExpandVariables(instrumentType);
            ticker = VariableManager.ExpandVariables(ticker);

            #region sql

            var sql = $@"
                        select ab.ins_num from ab_tran ab
                        inner join instruments i on ab.ins_type = i.id_number
                        inner join header h on ab.ins_num = h.ins_num
                        where ab.current_flag = 1
                           and ab.tran_type = 2 
                           and i.name = '{instrumentType}'
                           and h.ticker = '{ticker}'";

            #endregion

            side = VariableManager.ExpandVariables(side);
            if (!StringConversion.TryStringToExactInt(side, out var s))
                StepLog.LogFatal($"Invalid side {side}");

            var insNums = SqlRunner.RunSqlToInts(sql);
            if (!insNums.Any())
                StepLog.LogFatal($"No instruments for {instrumentType} / {ticker}");
            if (insNums.Count > 1)
                StepLog.LogFatal($"Multiple instruments for {instrumentType} / {ticker} : {string.Join(",", insNums)}");
            else
                Response.LogResponse(
                    TradeRepository.Value.SetUnderlyingInstrumentByInsNum(tranHandle, insNums.First(), s));

        }

