            VariableManager.ExpandTableVariables(table);
            
            var t = TransactionContext.GetSingleTransactionFromContext();
            foreach (var row in table.Rows)
            {
                var isDefault = "False";
                if (table.ContainsColumn(TransactionFieldDefinitions.CommodityNomTranTypeDefault))
                    isDefault = row[TransactionFieldDefinitions.CommodityNomTranTypeDefault];

                var typeValue = (table.ContainsColumn(NomDetailsFieldDefinitions.TranTypeDesc) &&
                                 !table.ContainsColumn(TransactionFieldDefinitions.CommodityNomTranType))
                    ? GetTranTypeValueFromDescription(row[NomDetailsFieldDefinitions.TranTypeDesc])
                    : row[TransactionFieldDefinitions.CommodityNomTranType]; 
                
                var response = TradeRepository.Value.AddEntitlementNomTypes(t, EnumTTLTransactionSubObjectType.EntitlementsNomTranType, isDefault, typeValue);
                Response.LogResponse(response);
            }
        }

