[Then(@"the composer contains a transaction with test label ""(.*)""")]
        public void ThenTheComposerContainsATransactionWithTestLabel(string testLabel)
        {
            testLabel = TestLabel.Expand(testLabel);
            var composer = TransactionContext.GetSingleTransactionFromContext();
            var tranHandle =
                TradeRepository.Value.GetTransactionByIdentifier(testLabel, EnumTTLTranIdentifier.TestLabel);

            if (!tranHandle.Response.Success)
            {
                Response.LogResponse(tranHandle.Response);
                StepLog.LogFatal("Composer check failed");
            }

            if (tranHandle.None)
                StepLog.LogFatal($"Failed to find transaction '{testLabel}'");
            tranHandle.TestLabel = testLabel;

            var ok = ComposerContainsLinkedDeal(composer, tranHandle);
            if (!ok)
                StepLog.LogFatal($"Composer does not contain {testLabel}");
        }

[When(@"I add to the composer a transaction with test label ""(.*)""")]
        public void WhenIAddToTheComposerATransactionWithTestLabel(string testLabel)
        {
            testLabel = TestLabel.Expand(testLabel);
            var composer = TransactionContext.GetSingleTransactionFromContext();
            var tranHandle =
                TradeRepository.Value.GetTransactionByIdentifier(testLabel, EnumTTLTranIdentifier.TestLabel);
            Response.LogResponse(tranHandle.Response);
            if (!tranHandle.Response.Success)
                StepLog.LogFatal("Add failed");

            if (tranHandle.None)
                StepLog.LogFatal($"Failed to find transaction '{testLabel}'");
            tranHandle.TestLabel = testLabel;

            var response = TradeRepository.Value.ComposerAddLinkedDeal(composer, tranHandle);
            Response.LogResponse(response);
        }

