[When("I cancel the loan rollover")]
        [When("I cancel the loan roll over")]
        [StepDefinitionDescription(
            Documentation =
                "Cancels the roll-over of the previously specified loan."
        )]
        public void WhenICancelTheLoanRollover()
        {
            var loan = TransactionContext.GetSingleTransactionFromContext();
            var sql = $@"select b.deal_num
                            from roll_over_aux a
                            inner join roll_over_aux b on a.roll_over_id = b.roll_over_id
                                                and a.deal_num<> b.deal_num
                            where a.deal_num = {loan.DealNum}
                            order by b.deal_num desc";
            var dealNum = SqlRunner.RunSqlToInts(sql);
            if (!dealNum.Any())
                StepLog.LogFatal("Transaction has not been rolled");
            var d = _tradeRepository.Value.GetTransactionByDealNum(dealNum.First());
            if (d != null)
            {
                Response.LogResponse(d.Response);
                var response = _tradeRepository.Value.ProcessTransactionToStatus(d, (int)EnumTTLTranStatus.Deleted);
                Response.LogResponse(response.Response);
            }
            else
                StepLog.LogFatal("failed to get transaction to cancel roll-over");
        }

