[OptionalColumnGroup(GroupName = nameof(ColumnGroups.PowerVolumeUploadAttributes))]
        [Given("the power volume schedule for leg (.*) is as follows")]
        [Then("the power volume schedule for leg (.*) is as follows")]
        public void GivenThePowerVolumeScheduleForLegIsAsFollows(int leg, Table expectedVolumes)
        {
            OpenlinkStepParameters.CheckTable(expectedVolumes);
            VariableManager.ExpandTableVariables(expectedVolumes);
            var existingTransactions = TransactionContext.GetMultipleTransactionsFromContext();
            var beginRange = DateTime.MaxValue;
            var endRange = DateTime.MinValue;

            foreach (var r in expectedVolumes.Rows)
            {
                if (!r.TryGetString(TransactionFieldDefinitions.PwrScheduleStartDateTime, out var startDateStr) &&
                    !r.TryGetString(TransactionFieldDefinitions.PwrScheduleGmtStartDateTime, out startDateStr))
                    StepLog.LogError("Start date should be specified");
                else if (!StringConversion.TryStringToDateTime(startDateStr, out var start))
                    StepLog.LogError($"Invalid start date {startDateStr}");
                else beginRange = start < beginRange ? start : beginRange;

                if (!r.TryGetString(TransactionFieldDefinitions.PwrScheduleEndDateTime, out var endDateStr) &&
                    !r.TryGetString(TransactionFieldDefinitions.PwrScheduleGmtEndDateTime, out endDateStr))
                    StepLog.LogError("End date should be specified");
                else if (!StringConversion.TryStringToDateTime(endDateStr, out var end))
                    StepLog.LogError($"Invalid end date {endDateStr}");
                else endRange = end > endRange ? end : endRange;
            }

            if (!StepLog.HasErrors())
            {
                var actualVolumesHandle = GetPowerSchedulesInRange(existingTransactions, leg, beginRange, endRange);
                if (!actualVolumesHandle.Response.Success)
                    Response.LogResponse(actualVolumesHandle.Response);
                else
                {
                    EndurTableComparer.Value.AssertTableContains(expectedVolumes, actualVolumesHandle);
                }
            }
        }

