[When(@"I set column ""(.*)"" row (.*) to ""(.*)""")]
        public void WhenISetColumnRowTo(string column, int rowNum, string value)
        {
            var r = CommonSelectContext.GetResults();
            if (rowNum < 0 || rowNum > r.Rows.Count)
                StepLog.LogFatal($"row {rowNum} out of range");
            if (!r.Columns.Contains(column))
                StepLog.LogFatal($"Unrecognised column {column}");

            r.Rows[rowNum][column] = value;
        }

