[When("I delete from the user table the following data")]
        [StepDefinitionDescription(Documentation =
            "Deletes rows that match the supplied table. Must be preceded by 'Given a user table called <name> exists'")]
        public void WhenIDeleteFromTheUserTableTheFollowingData(Table dataToDelete)
        {
            VariableManager.ExpandTableVariables(dataToDelete);
            var userTableName = TriangleScenarioContext.GetOrError<string>(UserTableContext, "no prior user table");

            // Build a table that matches the structure of the user table
            var structureHandle = EndurDatabaseRepository.Value.GetUserTableStructure(userTableName);

            // Remove any columns that are not mentioned in the Specflow table
            foreach (var columnName in EndurTableRepository.Value.GetColumnNames(structureHandle))
                if (!dataToDelete.Header.Contains(columnName))
                    EndurTableRepository.Value.DeleteColumn(structureHandle, columnName);

            UpdateTable(dataToDelete, structureHandle, UpdateType.Insert);
            var numRowsDeleted = EndurDatabaseRepository.Value.DeleteFromUserTable(userTableName, structureHandle);
            StepLog.LogDebug($"Deleted {numRowsDeleted} rows");
        }

