[When("I update the user table with the following data")]
        [StepDefinitionDescription(Documentation =
            "Updates the user table with specified data.  Logical key fields must be identified by including a '*' suffix in the column name.  Any data that is not already in the user table (based on logical keys) is silently ignored: this step only updates existing data - it never inserts data. Must be preceded by 'Given a user table called <name> exists'")]
        public void WhenIUpdateTheUserTableWithTheFollowingData(Table dataToUpdate)
        {
            VariableManager.ExpandTableVariables(dataToUpdate);
            var userTableName = TriangleScenarioContext.GetOrError<string>(UserTableContext, "no prior user table");
            var logicalKeys = string.Join(",",
                dataToUpdate.GetColumnHeadings().Where(ch => ch.IsPrimaryKey).Select(ch => ch.Heading));
            if (!logicalKeys.Any())
                StepLog.LogFatal("At least one column must be identified as a key column by annotating it with a '*'");

            var structureHandle = EndurDatabaseRepository.Value.GetUserTableStructure(userTableName);
            UpdateTable(dataToUpdate, structureHandle, UpdateType.Insert);

            var response = EndurDatabaseRepository.Value.UpdateUserTable(userTableName, structureHandle, logicalKeys);
            Response.LogResponse(response);
        }

