[When(@"I wait for workflow ""(.*)"" to complete")]
        [When(@"I wait for a workflow called ""(.*)"" to complete")]
        [StepDefinitionDescription(
            Documentation =
                "Waits for the named workflow to complete.  Succeeds immediately if the workflow has already completed.  A workflow could complete with a status of Failed or Succeeded.  If you wish to wait for a workflow to complete successfully, first wait for it to complete and then assert that it is status Succeeded.")]
        public void WhenIWaitForAWorkflowToComplete(string name)
        {
            name = VariableManager.ExpandVariables(name);
            GivenAWorkflowCalledExists(name);
            RepeaterFactory.Repeater.RepeatUntil(() =>
            {
                var response = _workflowRepository.Value.CheckWorkflowStatus(name, "Running");
                return response.Success == false;
            }, "Timeout before workflow completed");
        }

